window.__OPENSTAX_PHYSICS__[22] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:33:30.906Z","number":22,"code":"ch22","slug":"the-atom","title":"The Atom","titleVi":"Vật Lý Nguyên Tử & Hạt Nhân (The Atom & Radioactivity)","sections":[{"uid":"hsphys.ch22.sec00","moduleId":"m54583","number":"22.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch22.sec00.sub01","title":"Chapter Introduction","summaryVi":null,"paragraphs":["From childhood on, we learn that atoms are a substructure of all things around us, from the air we breathe to the autumn leaves that blanket a forest trail. Invisible to the eye, the atoms have properties that are used to explain many phenomena—a theme found throughout this text. In this chapter, we discuss the discovery of atoms and their own substructures. We will then learn about the forces that keep them together and the tremendous energy they release when we break them apart. Finally, we will see how the knowledge and manipulation of atoms allows us to better understand geology, biology, and the world around us."],"figures":[{"sourceId":"fs-id1167064876028","filename":"CNX_HSPhysics_22_00_Nanotube.jpg","relativePath":"media/CNX_HSPhysics_22_00_Nanotube.jpg","alt":"The microscopic image shows carbon atoms in a carbon nanotube."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch22.sec01","moduleId":"m54582","number":"22.1","slug":"the-structure-of-the-atom","title":"The Structure of the Atom","isIntroduction":false,"learningObjectives":["Describe Rutherford’s experiment and his model of the atom","Describe emission and absorption spectra of atoms","Describe the Bohr model of the atom","Calculate the energy of electrons when they change energy levels","Calculate the frequency and wavelength of emitted photons when electrons change energy levels","Describe the quantum model of the atom"],"bilingualGuide":{"notebookSummaryVi":"Thí nghiệm Rutherford, Mẫu nguyên tử Bohr, các mức năng lượng nguyên tử Hydro (E_n = -13.6 eV / n²) và Nguyên lý bất định Heisenberg.","wordProblemCues":[{"phraseEn":"photon emitted in transition","meaningVi":"Năng lượng photon phát ra khi nhảy mức","mathNotation":"hf = E_i - E_f"}],"commonTrapsVi":["Chuyển từ mức CAO xuống THẤP → PHÁT RA photon; từ THẤP lên CAO → HẤP THỤ photon!"]},"keyEquations":[{"name":"energy of hydrogen electron in an orbital","formula":"\\({E}_{n} = - \\frac{13.6\\,\\text{eV}}{{n}^{2}}(n = 1,2,3,...)\\)"},{"name":"energy of any hydrogen-like electron in orbital","formula":"\\({E}_{n} = \\frac{{Z}^{2}}{{n}^{2}}{E}_{o}(n = 1,2,3,...)\\)"},{"name":"wavelength of light emitted by an electron changing states","formula":"\\(\\frac{1}{\\lambda} = R(\\frac{1}{{n}_{f}{}^{2}} - \\frac{1}{{n}_{i}{}^{2}})\\)"},{"name":"wavelength of an orbital","formula":"\\(n{\\lambda}_{n} = 2\\pi {r}_{n}(n = 1,2,3,...)\\)"},{"name":"heisenberg’s uncertainty principle","formula":"\\(\\Delta x\\Delta p \\ge \\frac{h}{4\\pi}\\)"}],"subsections":[{"uid":"hsphys.ch22.sec01.sub01","title":"Rutherford’s Experiment","summaryVi":null,"paragraphs":["In the early 1900’s, the plum pudding model was the accepted model of the atom. Proposed in 1904 by J. J. Thomson, the model suggested that the atom was a spherical ball of positive charge, with negatively charged electrons scattered evenly throughout. In that model, the positive charges made up the pudding, while the electrons acted as isolated plums. During its short life, the model could be used to explain why most particles were neutral, although with an unbalanced number of plums, electrically charged atoms could exist.","When Ernest Rutherford began his gold foil experiment in 1909, it is unlikely that anyone would have expected that the plum pudding model would be challenged. However, using a radioactive source, a thin sheet of gold foil, and a phosphorescent screen, Rutherford would uncover something so great that he would later call it “the most incredible event that has ever happened to me in my life”[James, L. K. (1993). Nobel Laureates in Chemistry, 1901–1992 . Washington, DC: American Chemical Society.]","The experiment that Rutherford designed is shown in [Figure 22.1]. As you can see in, a radioactive source was placed in a lead container with a hole in one side to produce a beam of positively charged helium particles, called alpha particles . Then, a thin gold foil sheet was placed in the beam. When the high-energy alpha particles passed through the gold foil, they were scattered. The scattering was observed from the bright spots they produced when they struck the phosphor screen.","The expectation of the plum pudding model was that the high-energy alpha particles would be scattered only slightly by the presence of the gold sheet. Because the energy of the alpha particles was much higher than those typically associated with atoms, the alpha particles should have passed through the thin foil much like a supersonic bowling ball would crash through a few dozen rows of bowling pins. Any deflection was expected to be minor, and due primarily to the electrostatic Coulomb force between the alpha particles and the foil’s interior electric charges.","However, the true result was nothing of the sort. While the majority of alpha particles passed through the foil unobstructed, Rutherford and his collaborators Hans Geiger and Ernest Marsden found that alpha particles occasionally were scattered to large angles, and some even came back in the direction from which they came! The result, called Rutherford scattering , implied that the gold nuclei were actually very small when compared with the size of the gold atom. As shown in [Figure 22.1], the dense nucleus is surrounded by mostly empty space of the atom, an idea verified by the fact that only 1 in 8,000 particles was scattered backward.","Although the results of the experiment were published by his colleagues in 1909, it took Rutherford two years to convince himself of their meaning. Rutherford later wrote: “It was almost as incredible as if you fired a 15-inch shell at a piece of tissue paper and it came back and hit you. On consideration, I realized that this scattering backwards ... [meant] ... the greatest part of the mass of the atom was concentrated in a tiny nucleus.” In 1911, Rutherford published his analysis together with a proposed model of the atom, which was in part based on Geiger’s work from the previous year. As a result of the paper, the size of the nucleus was determined to be about \\({10}^{-15}\\) m, or 100,000 times smaller than the atom. That implies a huge density, on the order of \\({10}^{15}\\) g/cm 3 , much greater than any macroscopic matter.","Based on the size and mass of the nucleus revealed by his experiment, as well as the mass of electrons, Rutherford proposed the planetary model of the atom . The planetary model of the atom pictures low-mass electrons orbiting a large-mass nucleus. The sizes of the electron orbits are large compared with the size of the nucleus, and most of the atom is a vacuum. The model is analogous to how low-mass planets in our solar system orbit the large-mass Sun. In the atom, the attractive Coulomb force is analogous to gravitation in the planetary system (see [Figure 22.1]).","How did Rutherford figure out the structure of the atom without being able to see it? Explore the answer through this simulation of the famous experiment in which he disproved the plum pudding model by observing alpha particles bouncing off atoms and determining that they must have a small core."],"figures":[{"sourceId":"fs-id1167067186265","filename":"CNX_HSPhysics_22_01_GoldFoil.jpg","relativePath":"media/CNX_HSPhysics_22_01_GoldFoil.jpg","alt":"The figure shows the set-up for Rutherford’s experiment. It contains a source which emits alpha particles on a gold foil. The gold foil scatters the particles at different angles to a screen surrounding the gold foil."},{"sourceId":"fs-id1167067158336","filename":"CNX_HSPhysics_22_01_Scattering.jpg","relativePath":"media/CNX_HSPhysics_22_01_Scattering.jpg","alt":"The figure shows several circular atoms in a gold foil in Rutherford’s experiment. Each atom contains a tiny dot, known as the nucleus. The radius of an atom is 10-10  m whereas the radius of a nucleus is 10-15 m."},{"sourceId":"fs-id1167066793828","filename":"CNX_HSPHysics_22_01_Planetary.jpg","relativePath":"media/CNX_HSPHysics_22_01_Planetary.jpg","alt":"The figure shows the structure of an atom with a positive nucleus in the center and three negative spherical electrons circling around the center in their respective orbits."}],"tables":[]},{"uid":"hsphys.ch22.sec01.sub02","title":"Absorption and Emission Spectra","summaryVi":null,"paragraphs":["In 1900, Max Planck recognized that all energy radiated from a source is emitted by atoms in quantum states. How would that radical idea relate to the interior of an atom? The answer was first found by investigating the spectrum of light or emission spectrum produced when a gas is highly energized.","[Figure 22.1] shows how to isolate the emission spectrum of one such gas. The gas is placed in the discharge tube at the left, where it is energized to the point at which it begins to radiate energy or emit light. The radiated light is channeled by a thin slit and then passed through a diffraction grating, which will separate the light into its constituent wavelengths. The separated light will then strike the photographic film on the right.","The line spectrum shown in part (b) of [Figure 22.1] is the output shown on the film for excited iron. Note that this spectrum is not continuous but discrete. In other words, only particular wavelengths are emitted by the iron source. Why would that be the case?","The spectrum of light created by excited iron shows a variety of discrete wavelengths emitted within the visible spectrum. Each element, when excited to the appropriate degree, will create a discrete emission spectrum as in part (b) of [Figure 22.1]. However, the wavelengths emitted will vary from element to element. The emission spectrum for iron was chosen for [Figure 22.1] solely because a substantial portion of its emission spectrum is within the visible spectrum. [Figure 22.1] shows the emission spectrum for hydrogen. Note that, while discrete, a large portion of hydrogen emission takes place in the ultraviolet and infrared regions.","Just as an emission spectrum shows all discrete wavelengths emitted by a gas, an absorption spectrum will show all light that is absorbed by a gas. Black lines exist where the wavelengths are absorbed, with the remainder of the spectrum lit by light is free to pass through. What relationship do you think exists between the black lines of a gas’s absorption spectrum and the colored lines of its emission spectrum? [Figure 22.1] shows the absorption spectrum of the Sun. The black lines are called Fraunhofer lines , and they correspond to the wavelengths absorbed by gases in the Sun’s exterior."],"figures":[{"sourceId":"fs-id1167067218024","filename":"CNX_HSPhysics_22_01_Spectrum.jpg","relativePath":"media/CNX_HSPhysics_22_01_Spectrum.jpg","alt":"Part (a) shows the equipment set-up to observe the emission spectrum of iron and part (b) shows the resulting emission spectrum with discrete wavelengths."},{"sourceId":"fs-id1167067259108","filename":"CNX_HSPHysics_22_01_Hydrgen.jpg","relativePath":"media/CNX_HSPHysics_22_01_Hydrgen.jpg","alt":"The figure shows the hydrogen spectrum, with wavelengths from 91 nm  to 1875 nm. The spectrum from 91 nm to 122 nm is labelled as Layman series, the spectrum from 365 nm to 656 nm is labelled as Balmer series and the spectrum from 820 nm to 1875 nm is labelled as Paschen series."},{"sourceId":"fs-id1167067226382","filename":"CNX_HSPhysics_22_01_Absorption.jpg","relativePath":"media/CNX_HSPhysics_22_01_Absorption.jpg","alt":"The figure shows sun’s absorption spectrum, with wavelengths from 385 nm to 765 nm."}],"tables":[]},{"uid":"hsphys.ch22.sec01.sub03","title":"Bohr’s Explanation of the Hydrogen Spectrum","summaryVi":null,"paragraphs":["To tie the unique signatures of emission spectra to the composition of the atom itself would require clever thinking. Niels Bohr (1885–1962), a Danish physicist, did just that, by making immediate use of Rutherford’s planetary model of the atom. Bohr, shown in [Figure 22.1], became convinced of its validity and spent part of 1912 at Rutherford’s laboratory. In 1913, after returning to Copenhagen, he began publishing his theory of the simplest atom, hydrogen, based on Rutherford’s planetary model.","Bohr was able to derive the formula for the hydrogen spectrum using basic physics, the planetary model of the atom, and some very important new conjectures. His first conjecture was that only certain orbits are allowed: In other words, in an atom, the orbits of electrons are quantized. Each quantized orbit has a different distinct energy, and electrons can move to a higher orbit by absorbing energy or drop to a lower orbit by emitting energy. Because of the quantized orbits, the amount of energy emitted or absorbed must also be quantized, producing the discrete spectra seen in [Figure 22.1] and [Figure 22.1]. In equation form, the amount of energy absorbed or emitted can be found as","where \\({E}_{i}\\) refers to the energy of the initial quantized orbit, and \\({E}_{f}\\) refers to the energy of the final orbits. Furthermore, the wavelength emitted can be found using the equation","and relating the wavelength to the frequency found using the equation \\(v = f\\lambda\\), where v corresponds to the speed of light.","It makes sense that energy is involved in changing orbits. For example, a burst of energy is required for a satellite to climb to a higher orbit. What is not expected is that atomic orbits should be quantized. Quantization is not observed for satellites or planets, which can have any orbit, given the proper energy (see [Figure 22.1]).","[Figure 22.1] shows an energy-level diagram , a convenient way to display energy states. Each of the horizontal lines corresponds to the energy of an electron in a different orbital. Energy is plotted vertically with the lowest or ground state at the bottom and with excited states above. The vertical arrow downwards shows energy being emitted out of the atom due to an electron dropping from one excited state to another. That would correspond to a line shown on the atom’s emission spectrum. The Lyman series shown in [Figure 22.1] results from electrons dropping to the ground state, while the Balmer and Paschen series result to electrons dropping to the n = 2 and n = 3 states, respectively."],"figures":[{"sourceId":"fs-id1167067271401","filename":"CNX_HSPhysics_22_01_Bohr.jpg","relativePath":"media/CNX_HSPhysics_22_01_Bohr.jpg","alt":"A photo of Niels Bohr."},{"sourceId":"fs-id1167066857014","filename":"CNX_HSPHysics_22_01_Quantized.jpg","relativePath":"media/CNX_HSPHysics_22_01_Quantized.jpg","alt":"The figure shows Bohr’s atom model with circular electron orbits having distinct quantized energy levels. The figure also shows that energy is absorbed or emitted by an electron when it moves from one orbit (level) to another."},{"sourceId":"fs-id1167067021143","filename":"CNX_HSPHysics_22_01_NRGDiagram.jpg","relativePath":"media/CNX_HSPHysics_22_01_NRGDiagram.jpg","alt":"The figure shows energy levels on the vertical axis for the various orbits, from 1 to infinity and change in energy as an electron transitions from orbit 4 to 2."}],"tables":[]},{"uid":"hsphys.ch22.sec01.sub04","title":"Energy and Wavelength of Emitted Hydrogen Spectra","summaryVi":null,"paragraphs":["The energy associated with a particular orbital of a hydrogen atom can be found using the equation","where n corresponds to the orbital value from the atom’s nucleus. The negative value in the equation is based upon a baseline energy of zero when the electron is infinitely far from the atom. As a result, the negative value shows that energy is necessary to free the electron from its orbital state. The minimum energy to free the electron is also referred to as its binding energy . The equation is only valid for atoms with single electrons in their orbital shells (like hydrogen). For ionized atoms similar to hydrogen, the following formula may be used.","Please note that \\({E}_{o}\\) corresponds to –13.6 eV, as mentioned earlier. Additionally, \\(Z\\) refers to the atomic number of the element studied. The atomic number is the number of protons in the nucleus—it is different for each element. The above equation is derived from some basic physics principles, namely conservation of energy, conservation of angular momentum, Coulomb’s law, and centripetal force. There are three derivations that result in the orbital energy equations, and they are shown below. While you can use the energy equations without understanding the derivations, they will help to remind you of just how valuable those fundamental concepts are.","One primary difference between the planetary model of the solar system and the planetary model of the atom is the cause of the circular motion. While gravitation causes the motion of orbiting planets around an interior star, the Coulomb force is responsible for the circular shape of the electron’s orbit. The magnitude of the centripetal force is \\(\\frac{{m}_{e}{v}^{2}}{{r}_{n}}\\), while the magnitude of the Coulomb force is \\(\\frac{k(Z{q}_{e})({q}_{e})}{{r}_{e}{}^{2}}\\) . The assumption here is that the nucleus is more massive than the stationary electron, and the electron orbits about it. That is consistent with the planetary model of the atom. Equating the Coulomb force and the centripetal force,","which yields"],"figures":[],"tables":[]},{"uid":"hsphys.ch22.sec01.sub05","title":"Derivation 2 (Finding the Velocity of the Orbiting Electron)","summaryVi":null,"paragraphs":["Bohr was clever enough to find a way to calculate the electron orbital energies in hydrogen. That was an important first step that has been improved upon, but it is well worth repeating here, because it does correctly describe many characteristics of hydrogen. Assuming circular orbits, Bohr proposed that the angular momentum L of an electron in its orbit is also quantized, that is, it has only specific, discrete values. The value for L is given by the formula","where L is the angular momentum, m e is the electron’s mass, r n is the radius of the n th orbit, and h is Planck’s constant. Note that angular momentum is \\(L = I\\omega\\) . For a small object at a radius r, \\(I = m{r}^{2}\\), and \\(\\omega = \\frac{v}{r}\\), so that \\(L = I\\omega = (m{r}^{2})(\\frac{v}{r}) = mvr.\\) Quantization says that the value of mvr can only be equal to h / 2, 2 h / 2, 3 h / 2, etc. At the time, Bohr himself did not know why angular momentum should be quantized, but by using that assumption, he was able to calculate the energies in the hydrogen spectrum, something no one else had done at the time."],"figures":[],"tables":[]},{"uid":"hsphys.ch22.sec01.sub06","title":"Derivation 3 (Finding the Energy of the Orbiting Electron)","summaryVi":null,"paragraphs":["To get the electron orbital energies, we start by noting that the electron energy is the sum of its kinetic and potential energy.","Kinetic energy is the familiar \\(KE = \\frac{1}{2}m{v}^{2}\\), assuming the electron is not moving at a relativistic speed. Potential energy for the electron is electrical, or \\(PE = {q}_{e}V\\), where V is the potential due to the nucleus, which looks like a point charge. The nucleus has a positive charge \\(Z{q}_{e}\\); thus, \\(V = \\frac{kZ{q}_{e}}{{r}_{n}}\\), recalling an earlier equation for the potential due to a point charge from the chapter on Electricity and Magnetism. Since the electron’s charge is negative, we see that \\(PE = \\frac{- kZ{q}_{e}{}^{2}}{{r}_{n}}\\text{.}\\) Substituting the expressions for KE and PE,","Now we solve for r n and v using the equation for angular momentum \\(L = {m}_{e}v{r}_{n} = n\\frac{h}{2\\pi}(n = 1,2,3,...)\\), giving","and","Substituting the expression for r n and v into the above expressions for energy (KE and PE), and performing algebraic manipulation, yields","for the orbital energies of hydrogen-like atoms . Here, E o is the ground-state energy ( n = 1) for hydrogen ( Z = 1) and is given by","Thus, for hydrogen,","The relationship between orbital energies and orbital states for the hydrogen atom can be seen in [Figure 22.1].","The wavelength of light emitted by an atom can also be determined through basic derivations. Let us consider the energy of a photon emitted from a hydrogen atom in a downward transition, given by the equation","Substituting \\({E}_{n} = (\\frac{-13.6\\,\\text{e}\\text{V}}{{n}^{2}})\\), we get","Dividing both sides of the equation by hc gives us an expression for \\(\\frac{1}{\\lambda}\\),","It can be shown that","where R is the Rydberg constant .","Simplified, the formula for determining emitted wavelength can now be written as"],"figures":[{"sourceId":"fs-id1167063635765","filename":"CNX_HSPhysics_22_01_Detailed.jpg","relativePath":"media/CNX_HSPhysics_22_01_Detailed.jpg","alt":"The figure shows orbital energies on the vertical axis calculated for various orbits (from n=1 to n=infinity). The energy is –13.6eV for n=1, -3.40eV for n=2, –1.51eV for n=3, –0.85eV for n=4, –0.54eV for n=5 and 0 for n=infinity. The figure also shows transitions for Layman series (transitions to n=1 from higher levels), Balmer series (transitions to n=2 from higher levels) and Pacshen series (transitions to n=3 from higher levels)."}],"tables":[]},{"uid":"hsphys.ch22.sec01.sub07","title":"Limits of Bohr’s Theory and the Quantum Model of the Atom","summaryVi":null,"paragraphs":["There are limits to Bohr’s theory. It does not account for the interaction of bound electrons, so it cannot be fully applied to multielectron atoms, even one as simple as the two-electron helium atom. Bohr’s model is what we call semiclassical . The orbits are quantized (nonclassical) but are assumed to be simple circular paths (classical). As quantum mechanics was developed, it became clear that there are no well-defined orbits; rather, there are clouds of probability. Additionally, Bohr’s theory did not explain that some spectral lines are doublets or split into two when examined closely. While we shall examine a few of those aspects of quantum mechanics in more detail, it should be kept in mind that Bohr did not fail. Rather, he made very important steps along the path to greater knowledge and laid the foundation for all of atomic physics that has since evolved.","Following Bohr’s initial work on the hydrogen atom, a decade was to pass before Louis de Broglie proposed that matter has wave properties. The wave-like properties of matter were subsequently confirmed by observations of electron interference when scattered from crystals. Electrons can exist only in locations where they interfere constructively. How does that affect electrons in atomic orbits? When an electron is bound to an atom, its wavelength must fit into a small space, something like a standing wave on a string (see [Figure 22.1]). Orbits in which an electron can constructively interfere with itself are allowed. All orbits in which constructive interference cannot occur are not able to exist. Thus, only certain orbits are allowed. The wave nature of an electron, according to de Broglie, is why the orbits are quantized!","For a circular orbit, constructive interference occurs when the electron’s wavelength fits neatly into the circumference, so that wave crests always align with crests and wave troughs align with troughs, as shown in [Figure 22.1](b). More precisely, when an integral multiple of the electron’s wavelength equals the circumference of the orbit, constructive interference is obtained. In equation form, the condition for constructive interference and an allowed electron orbit is","where \\({\\lambda}_{n}\\) is the electron’s wavelength and r n is the radius of that circular orbit. [Figure 22.1] shows the third and fourth orbitals of a hydrogen atom."],"figures":[{"sourceId":"fs-id1167063820855","filename":"CNX_HSPhysics_22_01_DeBroglie.jpg","relativePath":"media/CNX_HSPhysics_22_01_DeBroglie.jpg","alt":"Part (a) shows standing waves on a string. With wave representing an electron parts (b) and (c) show allowed orbit (constructive interference) and forbidden orbit (destructive interference) respectively. The figure also shows equations—constructive interference occurs when 2πr=nλ where r is orbit radius and n is an integer and destructive interference occurs when 2πr’≠nλ’ where r’ is orbit radius and n is an integer."},{"sourceId":"fs-id1167063689907","filename":"CNX_HSPHysics_22_01_Orbitals.jpg","relativePath":"media/CNX_HSPHysics_22_01_Orbitals.jpg","alt":"The figure shows two circular orbits representing third and fourth allowed orbits with three and four wavelengths respectively."}],"tables":[]},{"uid":"hsphys.ch22.sec01.sub08","title":"Heisenberg Uncertainty","summaryVi":null,"paragraphs":["How does determining the location of an electron change its trajectory? The answer is fundamentally important—measurement affects the system being observed. It is impossible to measure a physical quantity exactly, and greater precision in measuring one quantity produces less precision in measuring a related quantity. It was Werner Heisenberg who first stated that limit to knowledge in 1929 as a result of his work on quantum mechanics and the wave characteristics of all particles (see [Figure 22.1]).","For example, you can measure the position of a moving electron by scattering light or other electrons from it. However, by doing so, you are giving the electron energy, and therefore imparting momentum to it. As a result, the momentum of the electron is affected and cannot be determined precisely. This change in momentum could be anywhere from close to zero up to the relative momentum of the electron ( \\(p \\approx h/\\lambda\\) ). Note that, in this case, the particle is an electron, but the principle applies to any particle.","Viewing the electron through the model of wave-particle duality, Heisenberg recognized that, because a wave is not located at one fixed point in space, there is an uncertainty associated with any electron’s position. That uncertainty in position, \\(\\Delta x\\) , is approximately equal to the wavelength of the particle. That is, \\(\\Delta x \\approx \\lambda\\) . There is an interesting trade-off between position and momentum. The uncertainty in an electron’s position can be reduced by using a shorter-wavelength electron, since \\(\\Delta x \\approx \\lambda\\) . But shortening the wavelength increases the uncertainty in momentum, since \\(\\Delta p \\approx h/\\lambda\\) . Conversely, the uncertainty in momentum can be reduced by using a longer-wavelength electron, but that increases the uncertainty in position. Mathematically, you can express the trade-off by multiplying the uncertainties. The wavelength cancels, leaving","\\(\\Delta x\\Delta p \\approx h.\\)","Therefore, if one uncertainty is reduced, the other must increase so that their product is \\(\\approx h\\) . With the use of advanced mathematics, Heisenberg showed that the best that can be done in a simultaneous measurement of position and momentum is","That relationship is known as the Heisenberg uncertainty principle ."],"figures":[{"sourceId":"fs-id1167067123987","filename":"CNX_HSPHysics_22_01_Heisenberg.jpg","relativePath":"media/CNX_HSPHysics_22_01_Heisenberg.jpg","alt":"A photo of Werner Heisenberg."}],"tables":[]},{"uid":"hsphys.ch22.sec01.sub09","title":"The Quantum Model of the Atom","summaryVi":null,"paragraphs":["Because of the wave characteristic of matter, the idea of well-defined orbits gives way to a model in which there is a cloud of probability, consistent with Heisenberg’s uncertainty principle. [Figure 22.1] shows how the principle applies to the ground state of hydrogen. If you try to follow the electron in some well-defined orbit using a probe that has a wavelength small enough to measure position accurately, you will instead knock the electron out of its orbit. Each measurement of the electron’s position will find it to be in a definite location somewhere near the nucleus. Repeated measurements reveal a cloud of probability like that in the figure, with each speck the location determined by a single measurement. There is not a well-defined, circular-orbit type of distribution. Nature again proves to be different on a small scale than on a macroscopic scale.","How did scientists figure out the structure of atoms without looking at them? Try out different models by shooting light at the atom. Use this simulation to see how the prediction of the model matches the experimental results."],"figures":[{"sourceId":"fs-id1167063521289","filename":"CNX_HSPhysics_22_01_Cloud.jpg","relativePath":"media/CNX_HSPhysics_22_01_Cloud.jpg","alt":"The figure shows a three dimensional axis with a spherical atom and a nucleus centered at the origin. The figure also shows a circle whose radius represents the most probable distance for an electron."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch22.sec01.ex01","number":"22.1.1","title":"Strategy","problem":"A hydrogen atom is struck by a photon. How much energy must be absorbed from the photon to raise the electron of the hydrogen atom from its ground state to its second orbital?","problemImages":[],"strategy":"The hydrogen atom has an atomic number of Z = 1. Raising the electron from the ground state to its second orbital will increase its orbital level from n = 1 to n = 2. The energy determined will be measured in electron-volts.","solution":"The amount of energy necessary to cause the change in electron state is the difference between the final and initial energies of the electron. The final energy state of the electron can be found using\n\\({E}_{n} = \\frac{{Z}^{2}}{{n}^{2}}{E}_{o}(n = 1,2,3,...)\\text{.}\\)\nKnowing the n and Z values for the hydrogen atom, and knowing that E o = –13.6 eV, the result is\n\\({E}_{f} = \\frac{{1}^{2}}{{2}^{2}}( - 13.6\\,\\text{eV}) = - 3.4\\,\\text{eV}.\\)\nThe original amount of energy associated with the electron is equivalent to the ground state orbital, or\n\\({E}_{O} = \\frac{{1}^{2}}{{1}^{2}}( - 13.6\\,\\text{eV}) = -13.6\\,\\text{eV}.\\)\nThe amount of energy necessary to change the orbital state of the electron can be found by determining the electron’s change in energy.\nΔ E =\nE\nf\n-\nE\no\n= (\n- 3.4 e V\n) - (\n- 13.6 e V\n) = + 10.2 e V","solutionImages":[],"solutionTables":[],"discussion":"The energy required to change the orbital state of the electron is positive. That means that for the electron to move to a state with greater energy, energy must be added to the atom. Should the electron drop back down to its original energy state, a change of –10.2 eV would take place, and 10.2 eV of energy would be emitted from the atom. Just as only quantum amounts of energy may be absorbed by the atom, only quantum amounts of energy can be emitted from the atom. That helps to explain many of the quantum light effects that you have learned about previously."},{"uid":"hsphys.ch22.sec01.ex02","number":"22.1.2","title":"Characteristic X-Ray Energy","problem":"Calculate the approximate energy of an X-ray emitted for an n = 2 to n = 1 transition in a tungsten anode in an X-ray tube.","problemImages":[],"strategy":"How do we calculate energies in a multiple-electron atom? In the case of characteristic X-rays, the following approximate calculation is reasonable. Characteristic X-rays are produced when an inner-shell vacancy is filled. Inner-shell electrons are nearer the nucleus than others in an atom and thus feel little net effect from the others. That is similar to what happens inside a charged conductor, where its excess charge is distributed over the surface so that it produces no electric field inside. It is reasonable to assume the inner-shell electrons have hydrogen-like energies, as given by\n\\({E}_{n} = \\frac{{Z}^{2}}{{n}^{2}}{E}_{o}(n = 1,2,3,...)\\)\nFor tungsten, Z = 74, so that the effective charge is 73.","solution":"The amount of energy given off as an X-ray is found using\n\\(\\Delta E = hf = {E}_{i} - {E}_{f},\\)\nwhere\n\\({E}_{f} = - \\frac{{Z}^{2}}{{1}^{2}}{E}_{o} = - \\frac{{73}^{2}}{1}(13.6\\,\\text{e}\\text{V}) = - 72.5\\,\\text{k}\\text{e}\\text{V}\\)\nand\n\\({E}_{i} = - \\frac{{Z}^{2}}{{2}^{2}}{E}_{o} = - \\frac{{73}^{2}}{4}(13.6\\,\\text{eV}) = -18.1\\,\\text{keV}.\\)\nThus,\nΔ E =\nE\ni\n-\nE\nf\n= (\n-18.1 k e V\n) - (\n-72.5 k e V\n) = 54.4 k e V.","solutionImages":[],"solutionTables":[],"discussion":"This large photon energy is typical of characteristic X-rays from heavy elements. It is large compared with other atomic emissions because it is produced when an inner-shell vacancy is filled, and inner-shell electrons are tightly bound. Characteristic X-ray energies become progressively larger for heavier elements because their energy increases approximately as Z 2 . Significant accelerating voltage is needed to create such inner-shell vacancies, because other shells are filled and you cannot simply bump one electron to a higher filled shell. You must remove it from the atom completely. In the case of tungsten, at least 72.5 kV is needed. Tungsten is a common anode material in X-ray tubes; so much of the energy of the impinging electrons is absorbed, raising its temperature, that a high-melting-point material like tungsten is required."},{"uid":"hsphys.ch22.sec01.ex03","number":"22.1.3","title":"Strategy","problem":"What wavelength of light is emitted by an electron dropping from the third orbital to the ground state of a hydrogen atom?","problemImages":[],"strategy":"The ground state of a hydrogen atom is considered the first orbital of the atom. As a result, n f = 1 and n i = 3. The Rydberg constant has already been determined and will be constant regardless of atom chosen.","solution":"\\(\\frac{1}{\\lambda} = R(\\frac{1}{{n}_{f}{}^{2}} - \\frac{1}{{n}_{i}{}^{2}})\\)\nFor the equation above, calculate wavelength based on the known energy states.\n\\(\\frac{1}{\\lambda} = 1.097\\, \\times \\,{10}^{7}(\\frac{1}{{1}^{2}} - \\frac{1}{{3}^{2}}) = 9.751 \\times {10}^{6}{\\text{m}}^{-1}\\)\nRearranging the equation for wavelength yields\n\\(\\lambda = 1.026\\, \\times \\,{10}^{-7}\\text{m} = 102.6\\,\\text{nm}.\\)","solutionImages":[],"solutionTables":[],"discussion":"This wavelength corresponds to light in the ultraviolet spectrum. As a result, we would not be able to see the photon of light emitted when an electron drops from its third to first energy state. However, it is worth noting that by supplying light of wavelength precisely 102.6 nm, we can cause the electron in hydrogen to move from its first to its third orbital state."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch22.sec01.feat01","type":"tip","title":"Tips for Success","text":"As you progress through the model of the atom, consider the effect that experimentation has on the scientific process. Ask yourself the following: What would our model of the atom be without Rutherford’s gold foil experiment? What further understanding of the atom would not have been gained? How would that affect our current technologies? Though often confusing, experiments taking place today to further understand composition of the atom could perhaps have a similar effect.","images":[]}],"summaryPoints":["Rutherford’s gold foil experiment provided evidence that the atom is composed of a small, dense nucleus with electrons occupying the mostly empty space around it.","Analysis of emission spectra shows that energy is emitted from energized gas in discrete quantities.","The Bohr model of the atom describes electrons existing in discrete orbits, with discrete energies emitted and absorbed as the electrons decrease and increase in orbital energy.","The energy emitted or absorbed by an electron as it changes energy state can be determined with the equation \\(\\Delta E = {E}_{i} - {E}_{f}\\), where \\({E}_{n} = \\frac{{Z}^{2}}{{n}^{2}}{E}_{o}(n = 1,2,3,...)\\) .","The wavelength of energy absorbed or emitted by an electron as it changes energy state can be determined by the equation \\(\\frac{1}{\\lambda} = R(\\frac{1}{{n}_{f}{}^{2}} - \\frac{1}{{n}_{i}{}^{2}})\\), where \\(R = 1.097\\, \\times \\,{10}^{7}{\\text{m}}^{-1}\\) .","Described as an electron cloud, the quantum model of the atom is the result of de Broglie waves and Heisenberg’s uncertainty principle."],"glossary":[{"term":"energy-level diagram","termVi":"Giản đồ các mức năng lượng","definition":"a diagram used to analyze the energy levels of electrons in the orbits of an atom","definitionVi":"Sơ đồ biểu diễn các mức năng lượng rời rạc của electron trong nguyên tử.","memoryTipVi":"E_n = -13.6 eV / n² (đối với nguyên tử Hydro)."},{"term":"excited state","termVi":"Trạng thái kích thích (n ≥ 2)","definition":"any state beyond the n = 1 orbital in which the electron stores energy","definitionVi":"Trạng thái nguyên tử hấp thụ năng lượng nhảy lên mức cao hơn mức cơ bản (kém bền, sẽ phát ra photon khi nhảy về mức thấp).","memoryTipVi":"hf = E_cao - E_thấp."},{"term":"Fraunhofer lines","termVi":"Các vạch tối hấp thụ Fraunhofer","definition":"black lines shown on an absorption spectrum that show the wavelengths absorbed by a gas","definitionVi":"Các vạch tối trong quang phổ Mặt Trời giúp nhận diện các nguyên tố hóa học có trong khí quyển Mặt Trời.","memoryTipVi":"Mỗi nguyên tố có bộ vạch quang phổ như \"dấu vân tay\" riêng."},{"term":"ground state","termVi":"Trạng thái cơ bản (n = 1)","definition":"the n =1 orbital of an electron","definitionVi":"Mức năng lượng thấp nhất và bền vững nhất của nguyên tử.","memoryTipVi":"Tại n = 1 của Hydro: E₁ = -13.6 eV."},{"term":"Heisenberg uncertainty principle","termVi":"Nguyên lý bất định Heisenberg","definition":"fundamental limit to the precision with which pairs of quantities such as momentum and position can be measured","definitionVi":"Không thể xác định chính xác đồng thời cả vị trí x lẫn động lượng p của một hạt lượng tử: Δx·Δp ≥ h/(4π).","memoryTipVi":"Bản chất lượng tử tự nhiên chứ không phải do máy đo kém!"},{"term":"hydrogen-like atom","termVi":"Ion giống nguyên tử Hydro (chỉ có 1 electron)","definition":"any atom with only a single electron","definitionVi":"Các ion chỉ còn đúng 1 electron quay quanh hạt nhân (như He⁺, Li²⁺).","memoryTipVi":"Tuân theo mẫu nguyên tử Bohr."},{"term":"planetary model of the atom","termVi":"Mô hình hành tinh nguyên tử","definition":"model of the atom that shows electrons orbiting like planets about a Sun-like nucleus","definitionVi":"Mô hình các electron chuyển động quanh hạt nhân dương ở tâm tương tự hành tinh quay quanh Mặt Trời.","memoryTipVi":"Được Niels Bohr hoàn thiện bằng tiên đề lượng tử."},{"term":"Rutherford scattering","termVi":"Thí nghiệm tán xạ hạt alpha Rutherford","definition":"scattering of alpha particles by gold nuclei in the gold foil experiment","definitionVi":"Bắn hạt α vào lá vàng mỏng phát hiện hạt nhân nguyên tử cực nhỏ, đặc và mang điện dương ở tâm.","memoryTipVi":"Bác bỏ mô hình bánh mận của Thomson."},{"term":"Rydberg constant","termVi":"Hằng số Rydberg (R_H)","definition":"a physical constant related to atomic spectra, with an established value of \\(1.097\\, \\times \\,{10}^{7}{\\text{m}}^{- 1}\\)","definitionVi":"Hằng số dùng để tính bước sóng các vạch quang phổ Hydro: R_H ≈ 1.097 × 10⁷ m⁻¹.","memoryTipVi":"1/λ = R_H (1/n_f² - 1/n_i²)."}],"assessments":[{"uid":"hsphys.ch22.sec01.q006","sourceId":"fs-id1167067197240","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Why would it most likely be difficult to observe quantized orbital states for satellites orbiting the earth?","images":[],"choices":[{"label":"a","text":"On a macroscopic level, the orbital states do exist for satellites orbiting Earth but are too closely spaced for us to see."},{"label":"b","text":"On a macroscopic level, the orbital states do not exist for satellites orbiting Earth."},{"label":"c","text":"On a macroscopic level, we cannot control the amount of energy that we give to an artificial satellite and thus control its orbital altitude."},{"label":"d","text":"On a macroscopic level, we cannot control the amount of energy that we give to an artificial satellite but we can control its orbital altitude."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch22.sec01.q007","sourceId":"fs-id1167063519649","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Do standing waves explain why electron orbitals are quantized?","images":[],"choices":[{"label":"a","text":"no"},{"label":"b","text":"yes"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch22.sec01.q008","sourceId":"eip-id1166850212885","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Some terms referring to the observation of light include emission spectrum and absorption spectrum . Based on these definitions, what would a reflection spectrum describe?","images":[],"choices":[{"label":"a","text":"The reflection spectrum would describe when incident waves are selectively reflected by a substance."},{"label":"b","text":"The reflection spectrum would describe when incident waves are completely reflected by a substance."},{"label":"c","text":"The reflection spectrum would describe when incident waves are not absorbed by a substance."},{"label":"d","text":"The reflection spectrum would describe when incident waves are completely absorbed by a substance."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch22.sec01.q009","sourceId":"eip-id1166849270252","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"If electrons are negatively charged and the nucleus is positively charged, why do they not attract and collide with each other?","images":[],"choices":[{"label":"a","text":"The pull from the nucleus provides a centrifugal force, which is not strong enough to draw the electrons into the nucleus."},{"label":"b","text":"The pull from the nucleus provides a centripetal force, which is not strong enough to draw the electrons into the nucleus."},{"label":"c","text":"The pull from the nucleus provides a helical motion."},{"label":"d","text":"The pull from the nucleus provides a cycloid motion."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch22.sec01.q010","sourceId":"fs-id1167066843281","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Why do Bohrs calculations for electron energies not work for all atoms?","images":[],"choices":[{"label":"a","text":"In atoms with more than one electron is an atomic shell, the electrons will interact. That requires a more complex formula than Bohrs calculations accounted for."},{"label":"b","text":"In atoms with 10 or more electorns in an atomic shell, the electrons will interact. That requires a more complex formula than Bohrs calculations accounted for."},{"label":"c","text":"In atoms with more than one electron in an atomic shell, the electrons will not interact. That requires a more complex formula than Bohrs calculations accounted for."},{"label":"d","text":"In atoms with 10 or more electrons in an atomic shell, the electrons will not interact. That requires a more complex formula than Bohrs calculations accounted for."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":6,"keyEquationCount":5,"subsectionCount":9,"workedExampleCount":3,"snapLabCount":0,"glossaryCount":9,"assessmentCount":5}},{"uid":"hsphys.ch22.sec02","moduleId":"m54580","number":"22.2","slug":"nuclear-forces-and-radioactivity","title":"Nuclear Forces and Radioactivity","isIntroduction":false,"learningObjectives":["Describe the structure and forces present within the nucleus","Explain the three types of radiation","Write nuclear equations associated with the various types of radioactive decay"],"bilingualGuide":{"notebookSummaryVi":"Cấu tạo hạt nhân (Z, A, Đồng vị), Lực hạt nhân mạnh và 3 loại phân rã phóng xạ (Alpha α, Beta β, Gamma γ).","wordProblemCues":[{"phraseEn":"mass number A & atomic number Z","meaningVi":"Bảo toàn số khối A và điện tích Z","mathNotation":"ΣA_i = ΣA_f; ΣZ_i = ΣZ_f"}],"commonTrapsVi":["Trong mọi phương trình hạt nhân, tổng A hai vế bằng nhau và tổng Z hai vế bằng nhau!"]},"keyEquations":[],"subsections":[{"uid":"hsphys.ch22.sec02.sub01","title":"The Structure of the Nucleus","summaryVi":null,"paragraphs":["At this point, you are likely familiar with the neutron and proton, the two fundamental particles that make up the nucleus of an atom. Those two particles, collectively called nucleons , make up the small interior portion of the atom. Both particles have nearly the same mass, although the neutron is about two parts in 1,000 more massive. The mass of a proton is equivalent to 1,836 electrons, while the mass of a neutron is equivalent to that of 1,839 electrons. That said, each of the particles is significantly more massive than the electron.","When describing the mass of objects on the scale of nucleons and atoms, it is most reasonable to measure their mass in terms of atoms. The atomic mass unit (u) was originally defined so that a neutral carbon atom would have a mass of exactly 12 u. Given that protons and neutrons are approximately the same mass, that there are six protons and six neutrons in a carbon atom, and that the mass of an electron is minuscule in comparison, measuring this way allows for both protons and neutrons to have masses close to 1 u. [Table_22_01] shows the mass of protons, neutrons, and electrons on the new scale.","Another other useful mass unit on the atomic scale is the \\(\\text{M}\\text{e}\\text{V}/{c}^{2}\\) . While rarely used in most contexts, it is convenient when one uses the equation \\(E = m{c}^{2}\\), as will be addressed later in this text.","To more completely characterize nuclei, let us also consider two other important quantities: the atomic number and the mass number. The atomic number , Z , represents the number of protons within a nucleus. That value determines the elemental quality of each atom. Every carbon atom, for instance, has a Z value of 6, whereas every oxygen atom has a Z value of 8. For clarification, only oxygen atoms may have a Z value of 8. If the Z value is not 8, the atom cannot be oxygen.","The mass number , A , represents the total number of protons and neutrons, or nucleons, within an atom. For an ordinary carbon atom the mass number would be 12, as there are typically six neutrons accompanying the six protons within the atom. In the case of carbon, the mass would be exactly 12 u. For oxygen, with a mass number of 16, the atomic mass is 15.994915 u. Of course, the difference is minor and can be ignored for most scenarios. Again, because the mass of an electron is so small compared to the nucleons, the mass number and the atomic mass can be essentially equivalent. [Figure 22.2] shows an example of Lithium-7, which has an atomic number of 3 and a mass number of 7.","How does the mass number help to differentiate one atom from another? If each atom of carbon has an atomic number of 6, then what is the value of including the mass number at all? The intent of the mass number is to differentiate between various isotopes of an atom. The term isotope refers to the variation of atoms based upon the number of neutrons within their nucleus. While it is most common for there to be six neutrons accompanying the six protons within a carbon atom, it is possible to find carbon atoms with seven neutrons or eight neutrons. Those carbon atoms are respectively referred to as carbon-13 and carbon-14 atoms, with their mass numbers being their primary distinction. The isotope distinction is an important one to make, as the number of neutrons within an atom can affect a number of its properties, not the least of which is nuclear stability.","To more easily identify various atoms, their atomic number and mass number are typically written in a form of representation called the nuclide . The nuclide form appears as follows: \\({}_{Z}^{A}X\\), where X is the atomic symbol and N represents the number of neutrons.","Let us look at a few examples of nuclides expressed in the \\({}_{Z}^{A}X\\) notation. The nucleus of the simplest atom, hydrogen, is a single proton, or \\(\\text{H}11\\) (the zero for no neutrons is often omitted). To check the symbol, refer to the periodic table—you see that the atomic number Z of hydrogen is 1. Since you are given that there are no neutrons, the mass number A is also 1. There is a scarce form of hydrogen found in nature called deuterium ; its nucleus has one proton and one neutron and, hence, twice the mass of common hydrogen. The symbol for deuterium is, thus, \\({}_{1}^{2}\\text{H}{}_{1}\\) . An even rarer—and radioactive—form of hydrogen is called tritium , since it has a single proton and two neutrons, and it is written \\({}_{1}^{3}\\text{H}{}_{2}\\) . The three varieties of hydrogen have nearly identical chemistries, but the nuclei differ greatly in mass, stability, and other characteristics. Again, the different nuclei are referred to as isotopes of the same element.","There is some redundancy in the symbols A , X , Z , and N . If the element X is known, then Z can be found in a periodic table. If both A and X are known, then N can also be determined by first finding Z ; then, N = A – Z . Thus the simpler notation for nuclides is","which is sufficient and is most commonly used. For example, in this simpler notation, the three isotopes of hydrogen are \\({}^{1}\\text{H}\\), \\({}^{2}\\text{H}\\), and \\({}^{3}\\text{H}\\) . For \\({}^{238}\\text{U}\\), should we need to know, we\ncan determine that Z = 92 for uranium from the periodic table, and thus, N = 238 - 92 = 146."],"figures":[{"sourceId":"fs-id1167066843126","filename":"CNX_HSPhysics_22_02_Lithium.jpg","relativePath":"media/CNX_HSPhysics_22_02_Lithium.jpg","alt":"The figure shows the Lithium-7 atom with three protons and four neutrons at the center (nucleus) and three electrons orbiting around the nucleus in different orbits."}],"tables":[{"sourceId":"Table_22_01","headers":["Proton Mass","Neutron Mass","Electron Mass"],"rows":[["Kilograms (kg)","\\(1.673\\, \\times \\,{10}^{-27}\\)","\\(1.675\\, \\times \\,{10}^{-27}\\)","\\(9.109\\, \\times \\,{10}^{-31}\\)"],["Atomic mass units (u)","\\(1.007\\)","\\(1.009\\)","\\(5.486\\, \\times \\,{10}^{-4}\\)"]]}]},{"uid":"hsphys.ch22.sec02.sub02","title":"Radioactivity and Nuclear Forces","summaryVi":null,"paragraphs":["In 1896, the French physicist Antoine Henri Becquerel (1852–1908) noticed something strange. When a uranium-rich mineral called pitchblende was placed on a completely opaque envelope containing a photographic plate, it darkened spots on the photographic plate.. Becquerel reasoned that the pitchblende must emit invisible rays capable of penetrating the opaque material. Stranger still was that no light was shining on the pitchblende, which means that the pitchblende was emitting the invisible rays continuously without having any energy input! There is an apparent violation of the law of conservation of energy, one that scientists can now explain using Einstein’s famous equation \\(E = m{c}^{2}\\text{.}\\) It was soon evident that Becquerel’s rays originate in the nuclei of the atoms and have other unique characteristics.","To this point, most reactions you have studied have been chemical reactions, which are reactions involving the electrons surrounding the atoms. However, two types of experimental evidence implied that Becquerel’s rays did not originate with electrons, but instead within the nucleus of an atom.","First, the radiation is found to be only associated with certain elements, such as uranium. Whether uranium was in the form of an element or compound was irrelevant to its radiation. In addition, the presence of radiation does not vary with temperature, pressure, or ionization state of the uranium atom. Since all of those factors affect electrons in an atom, the radiation cannot come from electron transitions, as atomic spectra do.","The huge energy emitted during each event is the second piece of evidence that the radiation cannot be atomic. Nuclear radiation has energies on the order of 10 6 eV per event, which is much greater than typical atomic energies that are a few eV, such as those observed in spectra and chemical reactions, and more than ten times as high as the most energetic X-rays.","But why would reactions within the nucleus take place? And what would cause an apparently stable structure to begin emitting energy? Was there something special about Becquerel’s uranium-rich pitchblende? To answer those questions, it is necessary to look into the structure of the nucleus. Though it is perhaps surprising, you will find that many of the same principles that we observe on a macroscopic level still apply to the nucleus.","A variety of experiments indicate that a nucleus behaves something like a tightly packed ball of nucleons, as illustrated in [Figure 22.2]. Those nucleons have large kinetic energies and, thus, move rapidly in very close contact. Nucleons can be separated by a large force, such as in a collision with another nucleus, but strongly resist being pushed closer together. The most compelling evidence that nucleons are closely packed in a nucleus is that the radius of a nucleus, r , is found to be approximately","where \\({r}_{o} =\\) 1.2 femtometer (fm) and A is the mass number of the nucleus.","Note that \\({r}^{3}∝A\\) . Since many nuclei are spherical, and the volume of a sphere is \\(V = (\\frac{4}{3})\\pi {r}^{3}\\), we see that \\(V∝A\\) —that is, the volume of a nucleus is proportional to the number of nucleons in it. That is what you expect if you pack nucleons so close that there is no empty space between them.","So what forces hold a nucleus together? After all, the nucleus is very small and its protons, being positive, should exert tremendous repulsive forces on one another. Considering that, it seems that the nucleus would be forced apart, not together!","The answer is that a previously unknown force holds the nucleus together and makes it into a tightly packed ball of nucleons. This force is known as the strong nuclear force . The strong force has such a short range that it quickly fall to zero over a distance of only 10 –15 meters. However, like glue, it is very strong when the nucleons get close to one another.","The balancing of the electromagnetic force with the nuclear forces is what allows the nucleus to maintain its spherical shape. If, for any reason, the electromagnetic force should overcome the nuclear force, components of the nucleus would be projected outward, creating the very radiation that Becquerel discovered!","Understanding why the nucleus would break apart can be partially explained using [Table_22_02]. The balance between the strong nuclear force and the electromagnetic force is a tenuous one. Recall that the attractive strong nuclear force exists between any two nucleons and acts over a very short range while the weaker repulsive electromagnetic force only acts between protons, although over a larger range. Considering the interactions, an imperfect balance between neutrons and protons can result in a nuclear reaction, with the result of regaining equilibrium.","The radiation discovered by Becquerel was due to the large number of protons present in his uranium-rich pitchblende. In short, the large number of protons caused the electromagnetic force to be greater than the strong nuclear force. To regain stability, the nucleus needed to undergo a nuclear reaction called alpha (α) decay ."],"figures":[{"sourceId":"fs-id1167067031835","filename":"CNX_HSPhysics_22_02_Nucleus.jpg","relativePath":"media/CNX_HSPhysics_22_02_Nucleus.jpg","alt":"The figure shows a nucleus with several spherical protons and neutrons which are held together."}],"tables":[{"sourceId":"Table_22_02","headers":["Range of Force","Direction","Nucleon Interaction","Magnitude of Force"],"rows":[["Electromagnetic Force","Long range, though decreasing by 1/r 2","Repulsive","Proton –proton repulsion","Relatively small"],["Strong Nuclear Force","Very short range, essentially zero at 1 femtometer","Attractive","Attraction between any two nucleons","100 times greater than the electromagnetic force"]]}]},{"uid":"hsphys.ch22.sec02.sub03","title":"The Three Types of Radiation","summaryVi":null,"paragraphs":["Radioactivity refers to the act of emitting particles or energy from the nucleus. When the uranium nucleus emits energetic nucleons in Becquerel’s experiment, the radioactive process causes the nucleus to alter in structure. The alteration is called radioactive decay . Any substance that undergoes radioactive decay is said to be radioactive . That those terms share a root with the term radiation should not be too surprising, as they all relate to the transmission of energy.","Alpha decay refers to the type of decay that takes place when too many protons exist in the nucleus. It is the most common type of decay and causes the nucleus to regain equilibrium between its two competing internal forces. During alpha decay, the nucleus ejects two protons and two neutrons, allowing the strong nuclear force to regain balance with the repulsive electromagnetic force. The nuclear equation for an alpha decay process can be shown as follows.","Three things to note as a result of the above equation:"],"figures":[{"sourceId":"fs-id1167063792999","filename":"CNX_HSPhysics_22_02_AlphaDecay.jpg","relativePath":"media/CNX_HSPhysics_22_02_AlphaDecay.jpg","alt":"The figure shows alpha decay of a nucleus (with several spherical protons and neutrons), resulting in release of an alpha particle, i.e. two protons and two neutrons."}],"tables":[]},{"uid":"hsphys.ch22.sec02.sub04","title":"Beta Decay","summaryVi":null,"paragraphs":["Like alpha decay, beta ( \\(\\beta\\) ) decay also takes place when there is an imbalance between neutrons and protons within the nucleus. For beta decay, however, a neutron is transformed into a proton and electron or vice versa. The transformation allows for the total mass number of the atom to remain the same, although the atomic number will increase by one (or decrease by one). Once again, the transformation of the neutron allows for a rebalancing of the strong nuclear and electromagnetic forces. The nuclear equation for a beta decay process is shown below.","\\({}_{Z}^{A}X{}_{N} \\to {}_{Z + 1}^{A}Y{}_{N - 1} + e + v\\)","The symbol \\(v\\) in the equation above stands for a high-energy particle called the neutrino . A nucleus may also emit a positron, and in that case Z decreases and N increases. It is beyond the scope of this section and will be discussed in further detail in the chapter on particles. It is worth noting, however, that the mass number and charge in all beta-decay reactions are conserved."],"figures":[{"sourceId":"fs-id1167067054814","filename":"CNX_HSPhysics_22_02_BetaDecay.jpg","relativePath":"media/CNX_HSPhysics_22_02_BetaDecay.jpg","alt":"The figure shows beta decay of a nucleus (with several spherical protons and neutrons), resulting in splitting of a neutron intro three particles, namely proton, electron and neutrino."}],"tables":[]},{"uid":"hsphys.ch22.sec02.sub05","title":"Gamma Decay","summaryVi":null,"paragraphs":["Gamma decay is a unique form of radiation that does not involve balancing forces within the nucleus. Gamma decay occurs when a nucleus drops from an excited state to the ground state. Recall that such a change in energy state will release energy from the nucleus in the form of a photon. The energy associated with the photon emitted is so great that its wavelength is shorter than that of an X-ray. Its nuclear equation is as follows."],"figures":[{"sourceId":"fs-id1167066946419","filename":"CNX_HSPhysics_22_02_GammaDecay.jpg","relativePath":"media/CNX_HSPhysics_22_02_GammaDecay.jpg","alt":"The figure shows gamma decay of a nucleus (with several spherical protons and neutrons), resulting in release of a gamma ray."}],"tables":[]},{"uid":"hsphys.ch22.sec02.sub06","title":"Properties of Radiation","summaryVi":null,"paragraphs":["The charges of the three radiated particles differ. Alpha particles, with two protons, carry a net charge of +2. Beta particles, with one electron, carry a net charge of –1. Meanwhile, gamma rays are solely photons, or light, and carry no charge. The difference in charge plays an important role in how the three radiations affect surrounding substances.","Alpha particles, being highly charged, will quickly interact with ions in the air and electrons within metals. As a result, they have a short range and short penetrating distance in most materials. Beta particles, being slightly less charged, have a larger range and larger penetrating distance. Gamma rays, on the other hand, have little electric interaction with particles and travel much farther. Two diagrams below show the importance of difference in penetration. [Table_22_03] shows the distance of radiation penetration, and [Figure 22.2] shows the influence various factors have on radiation penetration distance.","Watch beta decay occur for a collection of nuclei or for an individual nucleus. With this applet, individuals or groups of students can compare half-lives!"],"figures":[{"sourceId":"fs-id1167067013060","filename":"CNX_HSPhysics_22_02_RadPen.jpg","relativePath":"media/CNX_HSPhysics_22_02_RadPen.jpg","alt":"Part (a) shows penetration of two beta radiations with different energy levels in the same material—higher energy radiation achieves better penetration. Part (b) shows penetration of two beta radiations with same energy but in different materials (Pb and Li). The penetration is greater in Li due to lower electron density. Part (c) shows penetration of alpha, beta and gamma radiations with same energy in the same material. Gamma radiation has greatest penetration whereas alpha radiation has least penetration."}],"tables":[{"sourceId":"Table_22_03","headers":["Type of Radiation","Range"],"rows":[["\\(\\alpha\\) particles","A sheet of paper, a few cm of air, fractions of a millimeter of tissue"],["\\(\\beta\\) particles","A thin aluminum plate, tens of cm of tissue"],["\\(\\gamma\\) rays","Several cm of lead, meters of concrete"]]}]}],"workedExamples":[{"uid":"hsphys.ch22.sec02.ex01","number":"22.2.1","title":"Creating a Decay Equation","problem":"Write the complete decay equation in \\({}_{Z}^{A}X{}_{N}\\) notation for beta decay producing \\({}^{137}\\text{B}\\text{a}\\) . Refer to the periodic table for values of Z .","problemImages":[],"strategy":"Beta decay results in an increase in atomic number. As a result, the original (or parent) nucleus, must have an atomic number of one fewer proton.","solution":"The equation for beta decay is as follows\n\\(XZA{}_{N} \\to YZ + 1A{}_{N - 1} + e + v\\text{.}\\)\nConsidering that barium is the product (or daughter) nucleus and has an atomic number of 56, the original nucleus must be of an atomic number of 55. That corresponds to cesium, or Cs.\n\\(\\text{C}55137{\\text{s}}_{N} \\to \\text{B}56137{\\text{a}}_{N - 1} + e + v\\)\nThe number of neutrons in the parent cesium and daughter barium can be determined by subtracting the atomic number from the mass number (137 – 55 for cesium, 137 – 56 for barium). Substitute those values for the N and N – 1 subscripts in the above equation.\n\\(\\text{C}55137{\\text{s}}_{82} \\to \\text{B}56137{\\text{a}}_{81} + e + v\\)","solutionImages":[],"solutionTables":[],"discussion":"The terms parent and daughter nucleus refer to the reactants and products of a nuclear reaction. The terminology is not just used in this example, but in all nuclear reaction examples. The cesium-137 nuclear reaction poses a significant health risk, as its chemistry is similar to that of potassium and sodium, and so it can easily be concentrated in your cells if ingested."},{"uid":"hsphys.ch22.sec02.ex02","number":"22.2.2","title":"Alpha Decay Energy Found from Nuclear Masses","problem":"Find the energy emitted in the \\(\\alpha\\) decay of 239 Pu.","problemImages":[],"strategy":"Nuclear reaction energy, such as released in \\(\\alpha\\) decay, can be found using the equation \\(E = m{c}^{2}\\) . We must first find \\(\\Delta m\\), the difference in mass between the parent nucleus and the products of the decay.\nThe mass of pertinent particles is as follows\n239 Pu: 239.052157 u\n235 U: 235.043924 u\n4 He: 4.002602 u.","solution":"The decay equation for 239 Pu is\n\\(\\text{P}239\\text{u} \\to \\text{U}235 + \\text{H}4\\text{e}\\text{.}\\)\nDetermine the amount of mass lost between the parent and daughter nuclei.\n\\(\\Delta m = m({}^{239}\\text{P}\\,\\text{u}) - (m({}^{239}\\text{U})\\, + \\,m({}^{4}\\text{H}\\text{e}))\\Delta m = 239.052157\\,\\text{u} - (235.043924\\,\\text{u} + 4.002602\\,\\text{u})\\Delta m = 0.0005631\\,\\text{u}\\)\nNow we can find E by entering \\(\\Delta m\\) into the equation.\n\\(E = (\\Delta m){c}^{2} = (0.005631\\,\\text{u}){c}^{2}\\)\nAnd knowing that \\(1\\,\\text{u} = 931.5\\,\\text{m}\\text{e}\\text{V}/{c}^{2}\\), we can find that\n\\(E = (0.005631)(931.5\\,\\text{M}\\text{e}\\text{V}/{c}^{2})({c}^{2}) = 5.25\\,\\text{M}\\text{e}\\text{V}\\text{.}\\)","solutionImages":[],"solutionTables":[],"discussion":"The energy released in this \\(\\alpha\\) decay is in the MeV range, about 10 6 times as great as typical chemical reaction energies, consistent with previous discussions. Most of the energy becomes kinetic energy of the \\(\\alpha\\) particle (or 4 He nucleus), which moves away at high speed.\nThe energy carried away by the recoil of the 235 U nucleus is much smaller, in order to conserve momentum. The 235 U nucleus can be left in an excited state to later emit photons ( \\(\\gamma\\) rays). The decay is spontaneous and releases energy, because the products have less mass than the parent nucleus."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch22.sec02.feat01","type":"tip","title":"Tips for Success","text":"For most conceptual situations, the difference in mass between the proton and neutron is insubstantial. In fact, for calculations that require fewer than four significant digits, both the proton and neutron masses may be considered equivalent to one atomic mass unit. However, when determining the amount of energy released in a nuclear reaction, as in [Worked_Example_22_05], the difference in mass cannot be ignored.","images":[]},{"uid":"hsphys.ch22.sec02.feat02","type":"physics-in-action","title":"Radiation Detectors","text":"The first direct detection of radiation was Becquerel’s darkened photographic plate. Photographic film is still the most common detector of ionizing radiation, being used routinely in medical and dental X-rays. Nuclear radiation can also be captured on film, as seen in [Figure 22.2]. The mechanism for film exposure by radiation is similar to that by photons. A quantum of energy from a radioactive particle interacts with the emulsion and alters it chemically, thus exposing the film. Provided the radiation has more than the few eV of energy needed to induce the chemical change, the chemical alteration will occur. The amount of film darkening is related to the type of radiation and amount of exposure. The process is not 100 percent efficient, since not all incident radiation interacts and not all interactions produce the chemical change.\nFilm badges contain film similar to that used in this dental X-ray film. It is sandwiched between various absorbers to determine the penetrating ability of the radiation as well as the amount. Film badges are worn to determine radiation exposure. (credit: Werneuchen, Wikimedia Commons)\nAnother very common radiation detector is the Geiger tube . The clicking and buzzing sound we hear in dramatizations and documentaries, as well as in our own physics labs, is usually an audio output of events detected by a Geiger counter. These relatively inexpensive radiation detectors are based on the simple and sturdy Geiger tube, shown schematically in [Figure 22.2]. A conducting cylinder with a wire along its axis is filled with an insulating gas so that a voltage applied between the cylinder and wire produces almost no current. Ionizing radiation passing through the tube produces free ion pairs that are attracted to the wire and cylinder, forming a current that is detected as a count. Not every particle is detected, since some radiation can pass through without producing enough ionization. However, Geiger counters are very useful in producing a prompt output that reveals the existence and relative intensity of ionizing radiation.\n(a) Geiger counters such as this one are used for prompt monitoring of radiation levels, generally giving only relative intensity and not identifying the type or energy of the radiation. (credit: Tim Vickers, Wikimedia Commons) (b) Voltage applied between the cylinder and wire in a Geiger tube affects ions and electrons produced by radiation passing through the gas-filled cylinder. Ions move toward the cylinder and electrons toward the wire. The resulting current is detected and registered as a count.\nAnother radiation detection method records light produced when radiation interacts with materials. The energy of the radiation is sufficient to excite atoms in a material that may fluoresce, such as the phosphor used by Rutherford’s group. Materials called scintillators use a more complex process to convert radiation energy into light. Scintillators may be liquid or solid, and they can be very efficient. Their light output can provide information about the energy, charge, and type of radiation. Scintillator light flashes are very brief in duration, allowing the detection of a huge number of particles in short periods of time. Scintillation detectors are used in a variety of research and diagnostic applications. Among those are the detection of the radiation from distant galaxies using satellite-mounted equipment and the detection of exotic particles in accelerator laboratories.","images":[{"sourceId":"fs-id1167061253469","filename":"CNX_HSPhysics_22_02_PhotoFilm.jpg","relativePath":"media/CNX_HSPhysics_22_02_PhotoFilm.jpg","alt":"A photo of a film badge."},{"sourceId":"fs-id1167067025882","filename":"CNX_HSPhysics_22_02_Geiger.jpg","relativePath":"media/CNX_HSPhysics_22_02_Geiger.jpg","alt":"Part (a) shows the photo of a Geiger counter. Part (b) shows the working of Geiger counter as radiation comes from the left into a thin window and enters a cylinder filled with rarefied gas. The electronic counter on the right is used to detect the current."}]}],"summaryPoints":["The structure of the nucleus is defined by its two nucleons, the neutron and proton.","Atomic numbers and mass numbers are used to differentiate between various atoms and isotopes. Those numbers can be combined into an easily recognizable form called a nuclide .","The size and stability of the nucleus is based upon two forces: the electromagnetic force and strong nuclear force.","Radioactive decay is the alteration of the nucleus through the emission of particles or energy.","Alpha decay occurs when too many protons exist in the nucleus. It results in the ejection of an alpha particle, as described in the equation \\(XZA{}_{N} \\to YZ - 2A - 4{}_{N} + \\text{H}24{\\text{e}}_{}\\) .","Beta decay occurs when too many neutrons (or protons) exist in the nucleus. It results in the transmutation of a neutron into a proton, electron, and neutrino. The decay is expressed through the equation \\(XZA{}_{N} \\to YZ + 1A{}_{N - 1} + e + v\\) . (Beta decay may also transform a proton into a neutron.)","Gamma decay occurs when a nucleus in an excited state move to a more stable state, resulting in the release of a photon. Gamma decay is represented with the equation \\(XZA{}_{N} \\to {X}_{N} + \\gamma\\) .","The penetration distance of radiation depends on its energy, charge, and type of material it encounters."],"glossary":[{"term":"alpha decay","termVi":"Phân rã Alpha (α = ⁴₂He)","definition":"type of radioactive decay in which an atomic nucleus emits an alpha particle","definitionVi":"Hạt nhân phát ra hạt α (2 proton + 2 neutron) → Z giảm 2, A giảm 4.","memoryTipVi":"Tia α bị chặn dễ dàng chỉ bằng một tờ giấy!"},{"term":"atomic number","termVi":"Số hiệu nguyên tử (Z)","definition":"number of protons in a nucleus","definitionVi":"Số hạt PROTON trong hạt nhân — quyết định nguyên tố hóa học.","memoryTipVi":"Z = số proton."},{"term":"beta decay","termVi":"Phân rã Beta (β⁻ hoặc β⁺)","definition":"type of radioactive decay in which an atomic nucleus emits a beta particle","definitionVi":"Phát ra electron (β⁻: neutron → proton, Z tăng 1, A giữ nguyên) hoặc positron (β⁺).","memoryTipVi":"Số khối A KHÔNG ĐỔI trong phân rã β!"},{"term":"gamma decay","termVi":"Phóng xạ Gamma (γ)","definition":"type of radioactive decay in which an atomic nucleus emits a gamma ray","definitionVi":"Hạt nhân kích thích phát ra photon năng lượng cực cao (tia γ) — cả Z lẫn A đều giữ nguyên!","memoryTipVi":"Đâm xuyên cực mạnh, cần tấm chì dày mới chắn được."},{"term":"Geiger tube","termVi":"Ống đếm phóng xạ Geiger","definition":"very common radiation detector that usually gives an audio output","definitionVi":"Thiết bị phát hiện và đếm các hạt bức xạ ion hóa đi qua buồng khí.","memoryTipVi":"Phát tiếng lách tách đặc trưng khi gặp tia phóng xạ."},{"term":"isotope","termVi":"Đồng vị","definition":"nuclei having the same Z and different N’ s","definitionVi":"Các nguyên tử của cùng một nguyên tố (cùng số proton Z) nhưng KHÁC số neutron N (khác số khối A).","memoryTipVi":"Ví dụ: Carbon-12 và Carbon-14 đều có Z = 6."},{"term":"mass number","termVi":"Số khối (A = Z + N)","definition":"number of nucleons in a nucleus","definitionVi":"Tổng số proton (Z) và neutron (N) trong hạt nhân.","memoryTipVi":"Số neutron N = A - Z."},{"term":"nucleons","termVi":"Nuclôn (Hạt cấu tạo hạt nhân)","definition":"particles found inside nuclei","definitionVi":"Tên gọi chung của proton và neutron nằm trong hạt nhân nguyên tử.","memoryTipVi":"Tổng số nucleon chính là Số khối A."},{"term":"radioactive","termVi":"Có tính phóng xạ","definition":"substance or object that emits nuclear radiation","definitionVi":"Thuộc về hạt nhân không bền có khả năng tự phân rã.","memoryTipVi":"Ví dụ: Uranium-238, Carbon-14."},{"term":"radioactive decay","termVi":"Sự phân rã phóng xạ","definition":"process by which an atomic nucleus of an unstable atom loses mass and energy by emitting ionizing particles","definitionVi":"Sự biến đổi tự phát của một hạt nhân mẹ thành hạt nhân con bền hơn kèm phát tia phóng xạ.","memoryTipVi":"Bảo toàn điện tích Z và bảo toàn số khối A!"},{"term":"radioactivity","termVi":"Hiện tượng phóng xạ","definition":"emission of rays from the nuclei of atoms","definitionVi":"Quá trình hạt nhân không bền tự phát phân rã và phát ra các tia bức xạ (α, β, γ).","memoryTipVi":"Quá trình ngẫu nhiên, không phụ thuộc nhiệt độ hay áp suất."},{"term":"scintillator","termVi":"Đầu dò nhấp nháy","definition":"radiation detection method that records light produced when radiation interacts with materials","definitionVi":"Vật liệu phát ra chớp sáng nhỏ khi hấp thụ tia bức xạ ion hóa.","memoryTipVi":"Dùng trong máy chụp y học hạt nhân."},{"term":"strong nuclear force","termVi":"Lực hạt nhân (Tương tác mạnh)","definition":"attractive force that holds nucleons together within the nucleus","definitionVi":"Lực hút cực mạnh ở tầm cực ngắn (~10⁻¹⁵ m) giữ chặt các proton và neutron lại với nhau bất chấp lực đẩy tĩnh điện.","memoryTipVi":"Lực mạnh nhất trong 4 lực cơ bản của tự nhiên!"},{"term":"transmutation","termVi":"Sự biến đổi hạt nhân (chuyển thành nguyên tố khác)","definition":"process of changing elemental composition","definitionVi":"Sự thay đổi số proton Z khiến nguyên tố này biến thành nguyên tố hóa học khác.","memoryTipVi":"Xảy ra trong phóng xạ α và β."}],"assessments":[],"stats":{"learningObjectiveCount":3,"keyEquationCount":0,"subsectionCount":6,"workedExampleCount":2,"snapLabCount":0,"glossaryCount":14,"assessmentCount":0}},{"uid":"hsphys.ch22.sec03","moduleId":"m63183","number":"22.3","slug":"half-life-and-radiometric-dating","title":"Half Life and Radiometric Dating","isIntroduction":false,"learningObjectives":["Explain radioactive half-life and its role in radiometric dating","Calculate radioactive half-life and solve problems associated with radiometric dating"],"bilingualGuide":{"notebookSummaryVi":"Quy luật Chu kỳ bán rã N = N₀(1/2)^(t/T), Độ phóng xạ (Bq) và Định tuổi bằng Carbon-14.","wordProblemCues":[{"phraseEn":"remaining after n half-lives","meaningVi":"Lượng còn lại sau n chu kỳ bán rã","mathNotation":"N = N₀ / 2ⁿ"}],"commonTrapsVi":["Đọc kỹ đề hỏi lượng CÒN LẠI (N) hay lượng ĐÃ BỊ PHÂN RÃ (ΔN = N₀ - N)!"]},"keyEquations":[],"subsections":[{"uid":"hsphys.ch22.sec03.sub01","title":"Half-Life and the Rate of Radioactive Decay","summaryVi":null,"paragraphs":["Unstable nuclei decay. However, some nuclides decay faster than others. For example, radium and polonium, discovered by Marie and Pierre Curie, decay faster than uranium. That means they have shorter lifetimes, producing a greater rate of decay. Here we will explore half-life and activity, the quantitative terms for lifetime and rate of decay.","Why do we use the term like half-life rather than lifetime ? The answer can be found by examining [Figure 22.3], which shows how the number of radioactive nuclei in a sample decreases with time. The time in which half of the original number of nuclei decay is defined as the half-life , \\({t}_{\\frac{1}{2}}\\) . After one half-life passes, half of the remaining nuclei will decay in the next half-life. Then, half of that amount in turn decays in the following half-life. Therefore, the number of radioactive nuclei decreases from N to N / 2 in one half-life, to N / 4 in the next, to N / 8 in the next, and so on. Nuclear decay is an example of a purely statistical process.","The following equation gives the quantitative relationship between the original number of nuclei present at time zero \\(({N}_{O})\\) and the number \\((N)\\) at a later time t","where e = 2.71828... is the base of the natural logarithm, and \\(\\lambda\\) is the decay constant for the nuclide. The shorter the half-life, the larger is the value of \\(\\lambda\\), and the faster the exponential \\({e}^{- \\lambda t}\\) decreases with time. The decay constant can be found with the equation"],"figures":[{"sourceId":"fs-id1167065952757","filename":"CNX_HSPhysics_22_03_HalfLife.jpg","relativePath":"media/CNX_HSPhysics_22_03_HalfLife.jpg","alt":"The figure shows a graph and table with the readings. The exponential decay graph shows number of nuclides on the y axis and time (in half-lives) on the x-axis. The graph starts from 1000 at t=0 and decreases to half after every half-life. The range on the x-axis is from 0 to 10 half-lives."}],"tables":[]},{"uid":"hsphys.ch22.sec03.sub02","title":"Activity, the Rate of Decay","summaryVi":null,"paragraphs":["What do we mean when we say a source is highly radioactive? Generally, it means the number of decays per unit time is very high. We define activity R to be the rate of decay expressed in decays per unit time. In equation form, this is","where \\(\\Delta N\\) is the number of decays that occur in time \\(\\Delta t\\) .","Activity can also be determined through the equation","which shows that as the amount of radiative material ( N ) decreases, the rate of decay decreases as well.","The SI unit for activity is one decay per second and it is given the name becquerel (Bq) in honor of the discoverer of radioactivity. That is,","1 Bq = 1 decay/second .","Activity R is often expressed in other units, such as decays per minute or decays per year. One of the most common units for activity is the curie (Ci), defined to be the activity of 1 g of 226 Ra, in honor of Marie Curie’s work with radium. The definition of the curie is","or \\(3.70\\, \\times \\,{10}^{10}\\) decays per second."],"figures":[],"tables":[]},{"uid":"hsphys.ch22.sec03.sub03","title":"Radiometric Dating","summaryVi":null,"paragraphs":["Radioactive dating or radiometric dating is a clever use of naturally occurring radioactivity. Its most familiar application is carbon-14 dating . Carbon-14 is an isotope of carbon that is produced when solar neutrinos strike \\({}^{14}\\text{N}\\) particles within the atmosphere. Radioactive carbon has the same chemistry as stable carbon, and so it mixes into the biosphere, where it is consumed and becomes part of every living organism. Carbon-14 has an abundance of 1.3 parts per trillion of normal carbon, so if you know the number of carbon nuclei in an object (perhaps determined by mass and Avogadro’s number), you can multiply that number by \\(1.3\\, \\times \\,{10}^{- 12}\\) to find the number of \\({}^{14}\\text{C}\\) nuclei within the object. Over time, carbon-14 will naturally decay back to \\({}^{14}\\text{N}\\) with a half-life of 5,730 years (note that this is an example of beta decay). When an organism dies, carbon exchange with the environment ceases, and \\({}^{14}\\text{C}\\) is not replenished. By comparing the abundance of \\({}^{14}\\text{C}\\) in an artifact, such as mummy wrappings, with the normal abundance in living tissue, it is possible to determine the artifact’s age (or time since death). Carbon-14 dating can be used for biological tissues as old as 50 or 60 thousand years, but is most accurate for younger samples, since the abundance of \\({}^{14}\\text{C}\\) nuclei in them is greater.","One of the most famous cases of carbon-14 dating involves the Shroud of Turin, a long piece of fabric purported to be the burial shroud of Jesus (see [Figure 22.3]). This relic was first displayed in Turin in 1354 and was denounced as a fraud at that time by a French bishop. Its remarkable negative imprint of an apparently crucified body resembles the then-accepted image of Jesus. As a result, the relic has been remained controversial throughout the centuries. Carbon-14 dating was not performed on the shroud until 1988, when the process had been refined to the point where only a small amount of material needed to be destroyed. Samples were tested at three independent laboratories, each being given four pieces of cloth, with only one unidentified piece from the shroud, to avoid prejudice. All three laboratories found samples of the shroud contain 92 percent of the \\({}^{14}\\text{C}\\) found in living tissues, allowing the shroud to be dated (see [Worked_Example_22_07])."],"figures":[{"sourceId":"fs-id1167066182703","filename":"CNX_HSPhysics_22_03_Shroud.jpg","relativePath":"media/CNX_HSPhysics_22_03_Shroud.jpg","alt":"A photo of Shroud of Turin and its negative imprint."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch22.sec03.ex01","number":"22.3.1","title":"Carbon-11 Decay","problem":"Carbon-11 has a half-life of 20.334 min. (a) What is the decay constant for carbon-11?\nIf 1 kg of carbon-11 sample exists at the beginning of an hour, (b) how much material will remain at the end of the hour and (c) what will be the decay activity at that time?","problemImages":[],"strategy":"Since \\({N}_{O}\\) refers to the amount of carbon-11 at the start, then after one half-life, the amount of carbon-11 remaining will be \\({N}_{O}/2\\text{.}\\) The decay constant is equivalent to the probability that a nucleus will decay each second. As a result, the half-life will need to be converted to seconds.","solution":"(a)\n\\(N = {N}_{O}{e}^{- \\lambda t}\\)\nSince half of the carbon-11 remains after one half-life, \\(N/{N}_{O} = 0.5\\) .\n\\(0.5 = {e}^{- \\lambda t}\\)\nTake the natural logarithm of each side to isolate the decay constant.\n\\(ln(0.5) = - \\lambda t\\)\nConvert the 20.334 min to seconds.\n\\(- 0.693 = ( - \\lambda )(20.334min)(\\frac{60\\,\\text{s}}{1min}) - 0.693 = ( - \\lambda )(1,220.04\\,\\text{s})\\frac{- 0.693}{1,220.04\\,\\text{s}} = - \\lambda \\lambda = 5.68\\, \\times \\,{10}^{- 4}{\\text{s}}^{- 1}\\) (b) The amount of material after one hour can be found by using the equation\n\\(N = {N}_{O}{e}^{- \\lambda t},\\)\nwith t converted into seconds and N O written as 1,000 g\n\\(N = (1,000\\,\\text{g})e - (0.000568)(60.60)N = 129.4\\,g\\)\n(c) The decay activity after one hour can be found by using the equation\n\\(R = \\lambda N\\)\nfor the mass value after one hour.\n\\(R = \\lambda N = (0.000568\\,\\frac{\\text{decays}}{\\text{second}})(129.4\\,\\text{grams}) = 0.0735\\,\\text{Bq}\\)","solutionImages":[],"solutionTables":[],"discussion":"(a) The decay constant shows that 0.0568 percent of the nuclei in a carbon-11 sample will decay each second. Another way of considering the decay constant is that a given carbon-11 nuclei has a 0.0568 percent probability of decaying each second. The decay of carbon-11 allows it to be used in positron emission topography (PET) scans; however, its 20.334 min half-life does pose challenges for its administration.\n(b) One hour is nearly three full half-lives of the carbon-11 nucleus. As a result, one would expect the amount of sample remaining to be approximately one eighth of the original amount. The 129.4 g remaining is just a bit larger than one-eighth, which is sensible given a half-life of just over 20 min.\n(c) Label analysis shows that the unit of Becquerel is sensible, as there are 0.0735 g of carbon-11 decaying each second. That is smaller amount than at the beginning of the hour, when \\(R = (0.000568\\,\\frac{\\text{decay}}{\\text{s}})(1,000\\,\\text{g}) = 0.568\\) g of carbon-11 were decaying each second."},{"uid":"hsphys.ch22.sec03.ex02","number":"22.3.2","title":"How Old is the Shroud of Turin?","problem":"Calculate the age of the Shroud of Turin given that the amount of \\({}^{14}\\text{C}\\) found in it is 92 percent of that in living tissue.","problemImages":[],"strategy":"Because 92 percent of the \\({}^{14}\\text{C}\\) remains, \\(N/{N}_{O} = 0.92\\) . Therefore, the equation \\(N = {N}_{O}{e}^{- \\lambda t}\\) can be used to find \\(\\lambda t\\) . We also know that the half-life of \\({}^{14}\\text{C}\\) is 5,730 years, and so once \\(\\lambda t\\) is known, we can find \\(\\lambda\\) and then find t as requested. Here, we assume that the decrease in \\({}^{14}\\text{C}\\) is solely due to nuclear decay.","solution":"Solving the equation \\(N = {N}_{O}{e}^{- \\lambda t}\\) for \\(N/{N}_{O}\\) gives\n\\(\\frac{N}{{N}_{O}} = {e}^{- \\lambda t}.\\)\nThus,\n\\(0.92 = {e}^{- \\lambda t}.\\)\nTaking the natural logarithm of both sides of the equation yields\n\\(ln\\,0.92 = - \\lambda t\\)\nso that\n\\(- 0.0834 = - \\lambda t.\\)\nRearranging to isolate t gives\n\\(t = \\frac{0.0834}{\\lambda}.\\)\nNow, the equation \\(\\lambda = \\frac{0.693}{{t}_{1/2}}\\) can be used to find \\(\\lambda\\) for \\({}^{14}\\text{C}\\) . Solving for \\(\\lambda\\) and substituting the known half-life gives\n\\(\\lambda = \\frac{0.693}{{t}_{1/2}} = \\frac{0.693}{5,730\\,\\text{years}} = 1.21\\, \\times \\,{10}^{-4}{\\text{y}}^{-1}.\\) We enter that value into the previous equation to find t .\n\\(t = \\frac{0.0834}{1.21\\, \\times \\,{10}^{-4}} = 690\\,years.\\)","solutionImages":[],"solutionTables":[],"discussion":"This dates the material in the shroud to 1988–690 = 1300. Our calculation is only accurate to two digits, so that the year is rounded to 1300. The values obtained at the three independent laboratories gave a weighted average date of 1320 ± 60. That uncertainty is typical of carbon-14 dating and is due to the small amount of 14 C in living tissues, the amount of material available, and experimental uncertainties (reduced by having three independent measurements). That said, is it notable that the carbon-14 date is consistent with the first record of the shroud’s existence and certainly inconsistent with the period in which Jesus lived.\nThere are other noncarbon forms of radioactive dating. Rocks, for example, can sometimes be dated based on the decay of \\({}^{238}\\text{U.}\\) The decay series for \\({}^{238}\\text{U}\\) ends with \\({}^{206}\\text{P}\\text{b}\\), so the ratio of those nuclides in a rock can be used an indication of how long it has been since the rock solidified. Knowledge of the \\({}^{238}\\text{U}\\) half-life has shown, for example, that the oldest rocks on Earth solidified about \\(3.5\\, \\times {10}^{9}\\)\nyears ago."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch22.sec03.feat01","type":"tip","title":"Tips for Success","text":"A more precise definition of half-life is that each nucleus has a 50 percent chance of surviving for a time equal to one half-life. If an individual nucleus survives through that time, it still has a 50 percent chance of surviving through another half-life. Even if it happens to survive hundreds of half-lives, it still has a 50 percent chance of surviving through one more. Therefore, the decay of a nucleus is like random coin flipping. The chance of heads is 50 percent, no matter what has happened before.\nThe probability concept aligns with the traditional definition of half-life. Provided the number of nuclei is reasonably large, half of the original nuclei should decay during one half-life period.","images":[]}],"summaryPoints":["Radioactive half-life is the time it takes a sample of nuclei to decay to half of its original amount.","The rate of radioactive decay is defined as the sample’s activity, represented by the equation \\(R = \\frac{\\Delta N}{\\Delta t}\\) .","Knowing the half-life of a radioactive isotope allows for the process of radioactive dating to determine the age of a material.","If the half-life of a material is known, the age of the material can be found using the equation \\(N = {N}_{O}{e}^{- \\lambda t}\\) .","The age of organic material can be determined using the decay of the carbon-14 isotope, while the age of rocks can be determined using the decay of uranium-238."],"glossary":[{"term":"activity","termVi":"Độ phóng xạ (H hoặc R = λN)","definition":"rate of decay for radioactive nuclides","definitionVi":"Số hạt nhân phân rã trong 1 giây (đơn vị SI: Becquerel, Bq).","memoryTipVi":"Giảm theo thời gian cùng quy luật hàm mũ với số hạt N."},{"term":"becquerel","termVi":"Becơren (Bq)","definition":"SI unit for rate of decay of a radioactive material","definitionVi":"Đơn vị SI đo độ phóng xạ: 1 Bq = 1 phân rã / giây.","memoryTipVi":"Đặt theo tên Henri Becquerel."},{"term":"carbon-14 dating","termVi":"Định tuổi bằng Carbon-14","definition":"radioactive dating technique based on the radioactivity of carbon-14","definitionVi":"Phương pháp xác định tuổi hóa thạch/cổ vật hữu cơ dựa trên chu kỳ bán rã 5.730 năm của ¹⁴C.","memoryTipVi":"Hiệu quả cho mẫu vật dưới ~50.000 năm tuổi."},{"term":"decay constant","termVi":"Hằng số phóng xạ (λ)","definition":"quantity that is inversely proportional to the half-life and that is used in the equation for number of nuclei as a function of time","definitionVi":"Xác suất phân rã trên một đơn vị thời gian: λ = ln(2) / T₁/₂ ≈ 0.693 / T₁/₂.","memoryTipVi":"N(t) = N₀ · e^(-λt)."},{"term":"half-life","termVi":"Chu kỳ bán rã (T₁/₂)","definition":"time in which there is a 50 percent chance that a nucleus will decay","definitionVi":"Khoảng thời gian để MỘT NỬA số hạt nhân phóng xạ ban đầu bị phân rã: N = N₀ · (1/2)^(t/T).","memoryTipVi":"Sau 2 chu kỳ bán rã còn 1/4 (25%), sau 3 chu kỳ còn 1/8 (12.5%) — KHÔNG phải hết sạch sau 2 chu kỳ!"},{"term":"radioactive dating","termVi":"Định tuổi bằng đồng vị phóng xạ","definition":"application of radioactive decay in which the age of a material is determined by the amount of radioactivity of a particular type that occurs","definitionVi":"Xác định niên đại cổ vật hoặc đá địa chất dựa trên tỉ lệ đồng vị phóng xạ còn lại.","memoryTipVi":"Dùng C-14 cho mẫu hữu cơ, U-238 cho đá cổ hàng tỷ năm."}],"assessments":[{"uid":"hsphys.ch22.sec03.q001","sourceId":"fs-id1167064669300","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Provide an example of something that decreases in a manner similar to radioactive decay.","images":[],"choices":[{"label":"a","text":"The potential energy of an object falling under the influence of gravity"},{"label":"b","text":"The kinetic energy of a ball that is dropped from a building to the ground"},{"label":"c","text":"Theh charge transfer from an ebonite rod to fur"},{"label":"d","text":"The heat transfer from a hot to a cold object"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch22.sec03.q002","sourceId":"eip-id1166849855149","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"A sample of radioactive material has a decay constant of 0.05 s 1 . Why is it wrong to presume that the sample will take just 20 seconds to fully decay?","images":[],"choices":[{"label":"a","text":"The decay constant varies with the mass of the sample."},{"label":"b","text":"The decay constant results vary with the amount of the sample."},{"label":"c","text":"The decay constant represents a percentage of the sample that cannot decay."},{"label":"d","text":"The decay constant represents only the fraction of a sample that decays in a unit of time, not the decay of the entire sample."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":0,"subsectionCount":3,"workedExampleCount":2,"snapLabCount":0,"glossaryCount":6,"assessmentCount":2}},{"uid":"hsphys.ch22.sec04","moduleId":"m54574","number":"22.4","slug":"nuclear-fission-and-fusion","title":"Nuclear Fission and Fusion","isIntroduction":false,"learningObjectives":["Explain nuclear fission","Explain nuclear fusion","Describe how the processes of fission and fusion work in nuclear weapons and in generating nuclear power"],"bilingualGuide":{"notebookSummaryVi":"Phản ứng Phân hạch (Fission — tách hạt nhân nặng ²³⁵U) vs Phản ứng Nhiệt hạch (Fusion — tổng hợp hạt nhân nhẹ trên Mặt Trời).","wordProblemCues":[{"phraseEn":"fission vs fusion","meaningVi":"Phân hạch (tách ra) vs Nhiệt hạch (gộp lại)","mathNotation":"E = Δmc²"}],"commonTrapsVi":["Tính trên cùng 1 kg nhiên liệu, phản ứng Nhiệt hạch tỏa năng lượng lớn hơn Phân hạch nhiều lần và ít chất thải phóng xạ hơn!"]},"keyEquations":[],"subsections":[{"uid":"hsphys.ch22.sec04.sub01","title":"Nuclear Fission","summaryVi":null,"paragraphs":["In simplest terms, nuclear fission is the splitting of an atomic bond. Given that it requires great energy separate two nucleons, it may come as a surprise to learn that splitting a nucleus can release vast potential energy. And although it is true that huge amounts of energy can be released, considerable effort is needed to do so in practice.","An unstable atom will naturally decay, but it may take millions of years to do so. As a result, a physical catalyst is necessary to produce useful energy through nuclear fission. The catalyst typically occurs in the form of a free neutron, projected directly at the nucleus of a high-mass atom.","As shown in [Figure 22.4], a neutron strike can cause the nucleus to elongate, much like a drop of liquid water. This is why the model is known as the liquid drop model . As the nucleus elongates, nucleons are no longer so tightly packed, and the repulsive electromagnetic force can overcome the short-range strong nuclear force. The imbalance of forces can result in the two ends of the drop flying apart, with some of the nuclear binding energy released to the surroundings.","As you can imagine, the consequences of the nuclei splitting are substantial. When a nucleus is split, it is not only energy that is released, but a small number of neutrons as well. Those neutrons have the potential to cause further fission in other nuclei, especially if they are directed back toward the other nuclei by a dense shield or neutron reflector (see part (d) of [Figure 22.4]).","However, not every neutron produced by fission induces further fission. Some neutrons escape the fissionable material, while others interact with a nucleus without making it split. We can enhance the number of fissions produced by neutrons by having a large amount of fissionable material as well as a neutron reflector. The minimum amount necessary for self-sustained fission of a given nuclide is called its critical mass . Some nuclides, such as 239 Pu, produce more neutrons per fission than others, such as 235 U. Additionally, some nuclides are easier to make fission than others. In particular, 235 U and 239 Pu are easier to fission than the much more abundant 238 U. Both factors affect critical mass, which is smallest for 239 Pu. The self-sustained fission of nuclei is commonly referred to as a chain reaction , as shown in [Figure 22.4].","A chain reaction can have runaway results. If each atomic split results in two nuclei producing a new fission, the number of nuclear reactions will increase exponentially. One fission will produce two atoms, the next round of fission will create four atoms, the third round eight atoms, and so on. Of course, each time fission occurs, more energy will be emitted, further increasing the power of the atomic reaction. And that is just if two neutrons create fission reactions each round. Perhaps you can now see why so many people consider atomic energy to be an exciting energy source!","To make a self-sustained nuclear fission reactor with 235 U, it is necessary to slow down the neutrons. Water is very effective at this, since neutrons collide with protons in water molecules and lose energy. [Figure 22.4] shows a schematic of a reactor design called the pressurized water reactor .","Control rods containing nuclides that very strongly absorb neutrons are used to adjust neutron flux. To produce large amounts of power, reactors contain hundreds to thousands of critical masses, and the chain reaction easily becomes self-sustaining. Neutron flux must be carefully regulated to avoid an out-of-control exponential increase in the rate of fission.","Control rods help prevent overheating, perhaps even a meltdown or explosive disassembly. The water that is used to slow down neutrons, necessary to get them to induce fission in 235 U, and achieve criticality, provides a negative feedback for temperature increase. In case the reactor overheats and boils the water to steam or is breached, the absence of water kills the chain reaction. Considerable heat, however, can still be generated by the reactor’s radioactive fission products. Other safety features, thus, need to be incorporated in the event of a loss of coolant accident, including auxiliary cooling water and pumps.","The following are two interesting facts to consider:","How are those things possible? Doesn’t the fission reaction’s production of energy violate the conservation of energy? Furthermore, doesn’t the loss in mass in the reaction violate the conservation of mass? Those are important questions, and they can both be answered with one of the most famous equations in scientific history.","Recall that, according to Einstein’s theory, energy and mass are essentially the same thing. In the case of fission, the mass of the products is less than that of the reactants because the missing mass appears in the form of the energy released in the reaction, with a constant value of c 2 Joules of energy converted for each kilogram of material. The value of c 2 is substantial—from Einstein’s equation, the amount of energy in just 1 gram of mass would be enough to support the average U.S. citizen for more than 270 years! The example below will show you how a mass-energy transformation of this type takes place.","Start a chain reaction, or introduce nonradioactive isotopes to prevent one in this simulation . Use the applet to control energy production in a nuclear reactor!"],"figures":[{"sourceId":"fs-id1167060128213","filename":"CNX_HSPhysics_22_04_Fission.jpg","relativePath":"media/CNX_HSPhysics_22_04_Fission.jpg","alt":"Part (a) shows a neutron approaching a nucleus (with several protons and neutrons). Part (b) shows the deformation of the nucleus after the approaching neutron is absorbed. Part (c) shows two smaller nuclei formed from the original nucleus. Part (d) shows the neutrons released as two nuclei are formed after fission."},{"sourceId":"fs-id1167067076321","filename":"CNX_HSPhysics_22_04_Reaction.jpg","relativePath":"media/CNX_HSPhysics_22_04_Reaction.jpg","alt":"The figure shows chain reaction after fission as the neutrons released after fission of a nucleus cause fission in other nuclei."},{"sourceId":"fs-id1167067013417","filename":"CNX_HSPhysics_22_04_WatrReactr.jpg","relativePath":"media/CNX_HSPhysics_22_04_WatrReactr.jpg","alt":"The figure shows the schematic of a pressurized water reactor used for fission reaction."}],"tables":[]},{"uid":"hsphys.ch22.sec04.sub02","title":"Nuclear Fusion","summaryVi":null,"paragraphs":["Nuclear fusion is defined as the combining, or fusing, of two nuclei and, the combining of nuclei also results in an emission of energy. For many, the concept is counterintuitive. After all, if energy is released when a nucleus is split, how can it also be released when nucleons are combined together? The difference between fission and fusion, which results from the size of the nuclei involved, will be addressed next.","Remember that the structure of a nucleus is based on the interplay of the compressive nuclear strong force and the repulsive electromagnetic force. For nuclei that are less massive than iron, the nuclear force is actually stronger than that of the Coulomb force. As a result, when a low-mass nucleus absorbs nucleons, the added neutrons and protons bind the nucleus more tightly. The increased nuclear strong force does work on the nucleus, and energy is released.","Once the size of the created nucleus exceeds that of iron, the short-ranging nuclear force does not have the ability to bind a nucleus more tightly, and the emission of energy ceases. In fact, for fusion to occur for elements of greater mass than iron, energy must be added to the system! [Figure 22.4] shows an energy-mass curve commonly used to describe nuclear reactions. Notice the location of iron (Fe) on the graph. All low-mass nuclei to the left of iron release energy through fusion, while all high-mass particles to the right of iron produce energy through fission.","The major obstruction to fusion is the Coulomb repulsion force between nuclei. Since the attractive nuclear force that can fuse nuclei together is short ranged, the repulsion of like positive charges must be overcome in order to get nuclei close enough to induce fusion. [Figure 22.4] shows an approximate graph of the potential energy between two nuclei as a function of the distance between their centers. The graph resembles a hill with a well in its center. A ball rolled to the left must have enough kinetic energy to get over the hump before it falls into the deeper well with a net gain in energy. So it is with fusion. If the nuclei are given enough kinetic energy to overcome the electric potential energy due to repulsion, then they can combine, release energy, and fall into a deep well. One way to accomplish that end is to heat fusion fuel to high temperatures so that the kinetic energy of thermal motion is sufficient to get the nuclei together.","You might think that, in our Sun, nuclei are constantly coming into contact and fusing. However, this is only partially true. Only at the Sun’s core are the particles close enough and the temperature high enough for fusion to occur!","In the series of reactions below, the Sun produces energy by fusing protons, or hydrogen nuclei ( \\({}^{1}\\text{H}\\), by far the Sun’s most abundant nuclide) into helium nuclei \\({}^{4}\\text{H}\\text{e}\\) . The principal sequence of fusion reactions forms what is called the proton-proton cycle","\\({}^{1}\\text{H}{+}^{1}\\text{H}{\\to}^{2}\\text{H} + {e}^{+} + {v}_{e}(0.42\\,\\text{MeV}){}^{1}\\text{H}{+}^{2}\\text{H}{\\to}^{3}\\text{He} + \\gamma (5.49\\,\\text{MeV}){}^{3}\\text{He}{+}^{3}\\text{He}{\\to}^{4}\\text{He}{+}^{1}\\text{H}{+}^{1}\\text{H}(12.86\\,\\text{MeV}),\\)","where \\({e}^{+}\\) stands for a positron and \\({v}_{e}\\) is an electron neutrino. The energy in parentheses is released by the reaction. Note that the first two reactions must occur twice for the third to be possible, so the cycle consumes six protons ( \\({}^{1}\\text{H}\\) ) but gives back two. Furthermore, the two positrons produced will find two electrons and annihilate to form four more \\(\\gamma\\) rays, for a total of six. The overall cycle is thus","\\(2e - + {4}^{1}\\text{H} \\to 4\\,\\text{H}\\text{e} + 2{v}_{e} + 6\\gamma (26.7\\,\\text{MeV}),\\)","where the 26.7 MeV includes the annihilation energy of the positrons and electrons and is distributed among all the reaction products. The solar interior is dense, and the reactions occur deep in the Sun where temperatures are highest. It takes about 32,000 years for the energy to diffuse to the surface and radiate away. However, the neutrinos can carry their energy out of the Sun in less than two seconds, because they interact so weakly with other matter. Negative feedback in the Sun acts as a thermostat to regulate the overall energy output. For instance, if the interior of the Sun becomes hotter than normal, the reaction rate increases, producing energy that expands the interior. The expansion cools it and lowers the reaction rate. Conversely, if the interior becomes too cool, it contracts, increasing the temperature and therefore the reaction rate (see [Figure 22.4]). Stars like the Sun are stable for billions of years, until a significant fraction of their hydrogen has been depleted."],"figures":[{"sourceId":"fs-id1167063915092","filename":"CNX_HSPhysics_22_04_Curve.jpg","relativePath":"media/CNX_HSPhysics_22_04_Curve.jpg","alt":"The figure shows a graph with binding energy per nucleon on the y-axis and atomic mass on the x-axis. The range of y-axis is from 0 to 9 MeV and x-axis is 0 to 200. The atomic mass and binding energy of several elements are marked but it is stated that elements with low atomic mass and binding energy approximately between 1 MeV and 7 Me produce fusion energy."},{"sourceId":"fs-id1167067252702","filename":"CNX_HSPhysics_22_04_Well.jpg","relativePath":"media/CNX_HSPhysics_22_04_Well.jpg","alt":"The figure shows potential energy between nuclei on the y-axis and distance between them on the x-axis. The parabolic graph shows Coulomb’s repulsion hump with attractive pulling force on the left side of the hump and repelling repulsive force of the right side of the hump."},{"sourceId":"fs-id1167066790018","filename":"CNX_HSPhysics_22_04_Fusion.jpg","relativePath":"media/CNX_HSPhysics_22_04_Fusion.jpg","alt":"The figure shows fusion reaction in sun which has helium is in the center and hydrogen around it."}],"tables":[]},{"uid":"hsphys.ch22.sec04.sub03","title":"Nuclear Weapons and Nuclear Power","summaryVi":null,"paragraphs":["The world was in political turmoil when fission was discovered in 1938. Compounding the troubles, the possibility of a self-sustained chain reaction was immediately recognized by leading scientists the world over. The enormous energy known to be in nuclei, but considered inaccessible, now seemed to be available on a large scale.","Within months after the announcement of the discovery of fission, Adolf Hitler banned the export of uranium from newly occupied Czechoslovakia. It seemed that the possible military value of uranium had been recognized in Nazi Germany, and that a serious effort to build a nuclear bomb had begun.","Alarmed scientists, many of whom fled Nazi Germany, decided to take action. None was more famous or revered than Einstein. It was felt that his help was needed to get the American government to make a serious effort at constructing nuclear weapons as a matter of survival. Leo Szilard, a Hungarian physicist who had emigrated to America, took a draft of a letter to Einstein, who, although a pacifist, signed the final version. The letter was for President Franklin Roosevelt, warning of the German potential to build extremely powerful bombs of a new type. It was sent in August of 1939, just before the German invasion of Poland that marked the start of World War II.","It was not until December 6, 1941, the day before the Japanese attack on Pearl Harbor, that the United States made a massive commitment to building a nuclear bomb. The top secret Manhattan Project was a crash program aimed at beating the Germans. It was carried out in remote locations, such as Los Alamos, New Mexico, whenever possible, and eventually came to cost billions of dollars and employ the efforts of more than 100,000 people. J. Robert Oppenheimer (1904–1967), a talented physicist, was chosen to head the project. The first major step was made by Enrico Fermi and his group in December 1942, when they completed the first self-sustaining nuclear reactor. This first atomic pile , built in a squash court at the University of Chicago, proved that a fission chain reaction was possible.","Plutonium was recognized as easier to fission with neutrons and, hence, a superior fission material very early in the Manhattan Project . Plutonium availability was uncertain, and so a uranium bomb was developed simultaneously. [Figure 22.4] shows a gun-type bomb , which takes two subcritical uranium masses and shoots them together. To get an appreciable yield, the critical mass must be held together by the explosive charges inside the cannon barrel for a few microseconds. Since the buildup of the uranium chain reaction is relatively slow, the device to bring the critical mass together can be relatively simple. Owing to the fact that the rate of spontaneous fission is low, a neutron source is at the center the assembled critical mass.","Plutonium’s special properties necessitated a more sophisticated critical mass assembly, shown schematically in [Figure 22.4]. A spherical mass of plutonium is surrounded by shaped charges (high explosives that focus their blast) that implode the plutonium, crushing it into a smaller volume to form a critical mass. The implosion technique is faster and more effective, because it compresses three-dimensionally rather than one-dimensionally as in the gun-type bomb. Again, a neutron source is included to initiate the chain reaction.","Owing to its complexity, the plutonium bomb needed to be tested before there could be any attempt to use it. On July 16, 1945, the test named Trinity was conducted in the isolated Alamogordo Desert in New Mexico, about 200 miles south of Los Alamos (see [Figure 22.4]). A new age had begun. The yield of the Trinity device was about 10 kilotons (kT), the equivalent of 5,000 of the largest conventional bombs.","Although Germany surrendered on May 7, 1945, Japan had been steadfastly refusing to surrender for many months, resulting large numbers of civilian and military casualties. Invasion plans by the Allies estimated a million casualties of their own and untold losses of Japanese lives. The bomb was viewed as a way to end the war. The first bomb used was a gun-type uranium bomb dropped on Hiroshima on August 6 by the United States. Its yield of about 15 kT destroyed the city and killed an estimated 80,000 people, with 100,000 more being seriously injured. The second bomb was an implosion-type plutonium bomb dropped on Nagasaki only three days later. Its 20-kT yield killed at least 50,000 people, something less than Hiroshima because of the hilly terrain and the fact that it was a few kilometers off target. The Japanese were told that one bomb a week would be dropped until they surrendered unconditionally, which they did on August 14. In actuality, the United States had only enough plutonium for one more bomb, as yet unassembled.","Knowing that fusion produces several times more energy per kilogram of fuel than fission, some scientists pursued the idea of constructing a fusion bomb. The first such bomb was detonated by the United States several years after the first fission bombs, on October 31, 1952, at Eniwetok Atoll in the Pacific Ocean. It had a yield of 10 megatons (MT), about 670 times that of the fission bomb that destroyed Hiroshima. The Soviet Union followed with a fusion device of its own in August 1953, and a weapons race, beyond the aim of this text to discuss, continued until the end of the Cold War.","[Figure 22.4] shows a simple diagram of how a thermonuclear bomb is constructed. A fission bomb is exploded next to fusion fuel in the solid form of lithium deuteride. Before the shock wave blows it apart, \\(\\gamma\\) rays heat and compress the fuel, and neutrons create tritium through the reaction \\(n{+}^{6}\\text{L}\\text{i}{\\to}^{3}\\text{H}{+}^{4}\\text{H}\\text{e}\\) . Additional fusion and fission fuels are enclosed in a dense shell of \\({}^{238}\\text{U}\\) . At the same time that the uranium shell reflects the neutrons back into the fuel to enhance its fusion, the fast-moving neutrons cause the plentiful and inexpensive \\({}^{238}\\text{U}\\) to fission, part of what allows thermonuclear bombs to be so large.","Of course, not all applications of nuclear physics are as destructive as the weapons described above. Hundreds of nuclear fission power plants around the world attest to the fact that controlled fission is both practical and economical. Given growing concerns over global warming, nuclear power is often seen as a viable alternative to energy derived from fossil fuels.","For decades, fusion reactors have been deemed the energy of the future . A safer, cleaner, and more abundant potential source of energy than its fission counterpart, images of the fusion reactor have been conjured up each time the need for a renewable, environmentally friendly resource is discussed. Now, after more than half a century of speculating, some scientists believe that fusion reactors are nearly here.","In creating energy by combining atomic nuclei, the fusion reaction holds many advantages over fission. First, fusion reactions are more efficient, releasing 3 to 4 times more energy than fission per gram of fuel. Furthermore, unlike fission reactions that require heavy elements like uranium that are difficult to obtain, fusion requires light elements that are abundant in nature. The greatest advantage of the fusion reaction, however, is in its ability to be controlled. While traditional nuclear reactors create worries about meltdowns and radioactive waste, neither is a substantial concern with the fusion reaction. Consider that fusion reactions require a large amount of energy to overcome the repulsive Coulomb force and that the byproducts of a fusion reaction are largely limited to helium nuclei.","In order for fusion to occur, hydrogen isotopes of deuterium and tritium must be acquired. While deuterium can easily be gathered from ocean water, tritium is slightly more difficult to come by, though it can be manufactured from Earth’s abundant lithium. Once acquired, the hydrogen isotopes are injected into an empty vessel and subjected to temperature and pressure great enough to mimic the conditions at the core of our Sun. Using carefully controlled high-frequency radio waves, the hydrogen isotopes are broken into plasma and further controlled through an electromagnetic field. As the electromagnetic field continues to exert pressure on the hydrogen plasma, enough energy is supplied to cause the hydrogen plasma to fuse into helium.","Once the plasma fuses, high-velocity neutrons are ejected from the newly formed helium atoms. Those high velocity neutrons, carrying the excess energy stored within bonds of the original hydrogen, are able to travel unaffected by the applied magnetic field. In doing so, they strike a barrier around the nuclear reactor, transforming their excess energy to heat. The heat is then harvested to make steam that drives turbines. Hydrogen’s tremendous power is now usable!","The historical concern with nuclear fusion reactors is that the energy required to control the electromagnetic field is greater than the energy harvested from the hydrogen atoms. However, recent research by both Lockheed Martin engineers and scientists at the Lawrence Livermore National Laboratory has yielded exciting theoretical improvements in efficiency. At the time of this writing, a test facility called ITER (International Thermonuclear Experimental Reactor) is being constructed in southern France. A joint venture of the European Union, the United States, Japan, Russia, China, South Korea, and India, ITER is designed for further study into the future of nuclear fusion energy production."],"figures":[{"sourceId":"fs-id1167063667233","filename":"CNX_HSPhysics_22_04_GunType.jpg","relativePath":"media/CNX_HSPhysics_22_04_GunType.jpg","alt":"The figure shows the schematic of gun-type fusion bomb."},{"sourceId":"fs-id1167063541054","filename":"CNX_HSPhysics_22_04_Injection.jpg","relativePath":"media/CNX_HSPhysics_22_04_Injection.jpg","alt":"The figure shows the use of plutonium in a bomb. The spherical plutonium is surrounded by detonators, explosive lenses and shape charges that implode the plutonium which is crushed into a smaller volume."},{"sourceId":"fs-id1167063836687","filename":"CNX_HSPhysics_22_04_Trinity.jpg","relativePath":"media/CNX_HSPhysics_22_04_Trinity.jpg","alt":"A photo showing the Trinity test, the first nuclear bomb."},{"sourceId":"fs-id1167066774517","filename":"CNX_HSPhysics_22_04_Bomb.jpg","relativePath":"media/CNX_HSPhysics_22_04_Bomb.jpg","alt":"The figure shows schematic of a fusion bomb, in the shape of a closed cylinder. The outer portion has reflector and fission material and the inner portion has Styrofoam with gamma absorbers. The Styrofoam contains the shape charges, beryllium neutron reflector, lithium deuteride and the plutonium and uranium."},{"sourceId":"fs-id1167066836336","filename":"CNX_HSPhysics_22_04_Tokamok.jpg","relativePath":"media/CNX_HSPhysics_22_04_Tokamok.jpg","alt":"The figure shows parts of Tokamak confinement model."}],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch22.sec04.ex01","number":"22.4.1","title":"Calculating Energy from a Kilogram of Fissionable Fuel","problem":"Calculate the amount of energy produced by the fission of 1.00 kg of \\({}^{235}\\text{U}\\), given the average fission reaction of\n\\({}^{235}\\text{U produces 200 MeV.}\\)","problemImages":[],"strategy":"The total energy produced is the number of \\({}^{235}\\text{U}\\) atoms times the given energy per \\({}^{235}\\text{U}\\) fission. We should therefore find the number of \\({}^{235}\\text{U}\\) atoms in 1.00 kg.","solution":"The number of \\({}^{235}\\text{U}\\) atoms in 1.00 kg is Avogadro’s number times the number of moles. One mole of \\({}^{235}\\text{U}\\) has a mass of 235.04 g; thus, there are \\((1,000\\,\\text{g})/(235.04.00\\,\\text{g}/\\text{m}\\text{o}\\text{l}) = 4.25\\,\\text{m}\\text{o}\\text{l}\\) . The number of \\({}^{235}\\text{U}\\) atoms is therefore\n\\((4.25\\,\\text{mol})(6.02\\, \\times \\,{10}^{23}\\text{U}/\\text{mol}) = 2.56\\, \\times \\,{10}^{24}\\,\\text{atoms of}{}^{235}\\text{U}.\\)\nSo the total energy released is\n\\(E = (2.56\\, \\times \\,{10}^{24})(\\frac{200\\,\\text{MeV}}{{}^{235}\\text{U}})(\\frac{1.60\\, \\times \\,{10}^{-13}\\text{J}}{\\text{MeV}}) = 8.21 \\times {10}^{13}\\text{J}.\\)","solutionImages":[],"solutionTables":[],"discussion":"The result is another impressively large amount of energy, equivalent to about 14,000 barrels of crude oil or 600,000 gallons of gasoline. But, it is only one fourth the energy produced by the fusion of a kilogram of a mixture of deuterium and tritium. Even though each fission reaction yields about ten times the energy of a fusion reaction, the energy per kilogram of fission fuel is less, because there are far fewer moles per kilogram of the heavy nuclides. Fission fuel is also much scarcer than fusion fuel, and less than 1 percent of uranium (the 235 U) is readily usable."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch22.sec04.feat01","type":"tip","title":"Tips for Success","text":"Just as it is not possible for the elements to the left of iron in the figure to naturally fission, it is not possible for elements to the right of iron to naturally undergo fusion, as that process would require the addition of energy to occur. Furthermore, notice that elements commonly discussed in fission and fusion are elements that can provide the greatest change in binding energy, such as uranium and hydrogen.\nIron’s location on the energy-mass curve is important, and explains a number of its characteristics, including its role as an elemental endpoint in fusion reactions in stars.","images":[]}],"summaryPoints":["Nuclear fission is the splitting of an atomic bond, releasing a large amount of potential energy previously holding the atom together. The amount of energy released can be determined through the equation \\(E = m{c}^{2}\\) .","Nuclear fusion is the combining, or fusing together, of two nuclei. Energy is also released in nuclear fusion as the combined nuclei are closer together, resulting in a decreased strong nuclear force.","Fission was used in two nuclear weapons at the conclusion of World War II: the gun-type uranium bomb and the implosion-type plutonium bomb.","While fission has been used in both nuclear weapons and nuclear reactors, fusion is capable of releasing more energy per reaction. As a result, fusion is a well-researched, if not yet well-controlled, energy source."],"glossary":[{"term":"chain reaction","termVi":"Phản ứng dây chuyền","definition":"self-sustaining sequence of events, exemplified by the self-sustaining nature of a fission reaction at critical mass","definitionVi":"Các neutron sinh ra từ 1 phân hạch tiếp tục kích thích các hạt nhân khác phân hạch nối tiếp nhau.","memoryTipVi":"Trong lò phản ứng hạt nhân, thanh điều khiển giữ hệ số nhân k = 1."},{"term":"critical mass","termVi":"Khối lượng tới hạn","definition":"minimum amount necessary for self-sustained fission of a given nuclide","definitionVi":"Khối lượng tối thiểu của nhiên liệu phân hạch để duy trì được phản ứng dây chuyền tự tiếp diễn.","memoryTipVi":"Nhỏ hơn khối lượng tới hạn → neutron thoát ra ngoài quá nhiều, phản ứng tắt."},{"term":"liquid drop model","termVi":"Mô hình giọt chất lỏng (của hạt nhân)","definition":"model of the atomic nucleus (useful only to understand some of its features) in which nucleons in a nucleus act like atoms in a drop","definitionVi":"Mô hình coi hạt nhân nặng giống như một giọt chất lỏng bị dao động và tách đôi khi phân hạch.","memoryTipVi":"Do Niels Bohr và John Wheeler đề xuất."},{"term":"nuclear fission","termVi":"Phản ứng phân hạch","definition":"reaction in which a nucleus splits","definitionVi":"Hạt nhân rất nặng (như ²³⁵U) hấp thụ neutron vỡ thành 2 hạt nhân trung bình kèm giải phóng năng lượng lớn.","memoryTipVi":"Cơ sở của nhà máy điện hạt nhân hiện nay."},{"term":"nuclear fusion","termVi":"Phản ứng nhiệt hạch (Tổng hợp hạt nhân)","definition":"reaction in which two nuclei are combined, or fused, to form a larger nucleus","definitionVi":"Hai hạt nhân rất nhẹ (như Hydro) kết hợp thành hạt nhân nặng hơn (Heli) ở nhiệt độ cực cao, tỏa năng lượng khổng lồ.","memoryTipVi":"Nguồn năng lượng của Mặt Trời và các ngôi sao!"},{"term":"proton-proton cycle","termVi":"Chu trình proton–proton","definition":"combined reactions \\({}^{\\text{1}}\\text{H}{+}^{1}\\text{H} \\to {}^{2}\\text{H} + {e}^{-} + {v}_{e}.\\)\n\\({}^{\\text{1}}\\text{H}{+}^{2}\\text{H} \\to {}^{3}\\text{He} + \\gamma\\)\nand \\({}^{\\text{3}}\\text{He}{+}^{3}\\text{He} \\to {}^{4}\\text{He}{+}^{1}\\text{H}{+}^{1}\\text{H}\\)\nthat begins with hydrogen and ends with helium","definitionVi":"Chuỗi phản ứng nhiệt hạch trong lõi Mặt Trời biến đổi Hydro thành Heli và năng lượng bức xạ.","memoryTipVi":"Giúp Mặt Trời chiếu sáng hàng tỷ năm."}],"assessments":[{"uid":"hsphys.ch22.sec04.q004","sourceId":"fs-id1167066959740","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"If a nucleus elongates due to a neutron strike, which of the following forces will decrease?","images":[],"choices":[{"label":"a","text":"Nuclear force between neutrons only"},{"label":"b","text":"Coulomb force between protons only"},{"label":"c","text":"Strong nuclear force between all nucleons and Coulomb force between protons, but the strong force will decrease more"},{"label":"d","text":"Strong nuclear force between neutrons and Coulomb force between protons, but Coulomb force will decrease more"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":3,"keyEquationCount":0,"subsectionCount":3,"workedExampleCount":1,"snapLabCount":0,"glossaryCount":6,"assessmentCount":1}},{"uid":"hsphys.ch22.sec05","moduleId":"m54578","number":"22.5","slug":"medical-applications-of-radioactivity-diagnostic-imaging-and-radiation","title":"Medical Applications of Radioactivity: Diagnostic Imaging and Radiation","isIntroduction":false,"learningObjectives":["Describe how nuclear imaging works (e.g., radioisotope imaging, PET)","Describe the ionizing effects of radiation and how they can be used for medical treatment"],"bilingualGuide":{"notebookSummaryVi":"Ứng dụng đồng vị phóng xạ trong Chẩn đoán hình ảnh y khoa, Xạ trị ung thư và đơn vị liều bức xạ (rad, rem).","wordProblemCues":[{"phraseEn":"dose in rem = rad × RBE","meaningVi":"Liều tương đương sinh học","mathNotation":"rem = rad · RBE"}],"commonTrapsVi":["Hạt α ở ngoài da ít nguy hiểm, nhưng nếu hít/nuốt vào bên trong cơ thể thì cực kỳ nguy hiểm vì RBE rất cao!"]},"keyEquations":[{"name":"roentgen equivalent man","formula":"rem = rad × RBE"}],"subsections":[{"uid":"hsphys.ch22.sec05.sub01","title":"Medical Applications of Nuclear Physics","summaryVi":null,"paragraphs":["Applications of nuclear physics have become an integral part of modern life. From the bone scan that detects one cancer to the radioiodine treatment that cures another, nuclear radiation has diagnostic and therapeutic effects on medicine.","A host of medical imaging techniques employ nuclear radiation. What makes nuclear radiation so useful? First, \\(\\gamma\\) radiation can easily penetrate tissue; hence, it is a useful probe to monitor conditions inside the body. Second, nuclear radiation depends on the nuclide and not on the chemical compound it is in, so that a radioactive nuclide can be put into a compound designed for specific purposes. When that is done, the compound is said to be tagged . A tagged compound used for medical purposes is called a radiopharmaceutical . Radiation detectors external to the body can determine the location and concentration of a radiopharmaceutical to yield medically useful information. For example, certain drugs are concentrated in inflamed regions of the body, and their locations can aid diagnosis and treatment as seen in [Figure 22.5]. Another application utilizes a radiopharmaceutical that the body sends to bone cells, particularly those that are most active, to detect cancerous tumors or healing points. Images can then be produced of such bone scans. Clever use of radioisotopes determines the functioning of body organs, such as blood flow, heart muscle activity, and iodine uptake in the thyroid gland. For instance, a radioactive form of iodine can be used to monitor the thyroid, a radioactive thallium salt can be used to follow the blood stream, and radioactive gallium can be used for cancer imaging.","Once a radioactive compound has been ingested, a device like that shown in [Figure 22.5] is used to monitor nuclear activity. The device, called an Anger camera or gamma camera uses a piece of lead with holes bored through it. The gamma rays are redirected through the collimator to narrow their beam, and are then interpreted using a device called a scintillator. The computer analysis of detector signals produces an image. One of the disadvantages of this detection method is that there is no depth information (i.e., it provides a two-dimensional view of the tumor as opposed to a three-dimensional view), because radiation from any location under that detector produces a signal.","Single-photon-emission computer tomography (SPECT) used in conjunction with a CT scanner improves on the process carried out by the gamma camera. [Figure 22.5] shows a patient in a circular array of SPECT detectors that may be stationary or rotated, with detector output used by a computer to construct a detailed image. The spatial resolution of this technique is poor, but the three-dimensional image created results in a marked improvement in contrast.","Positron emission tomography (or PET) scans utilize images produced by \\({\\beta}^{+}\\) emitters. When the emitted positron β + encounters an electron, mutual annihilation occurs, producing two γ rays. Those \\(\\gamma\\) rays have identical 0.511 MeV energies (the energy comes from the destruction of an electron or positron mass) and they move directly away from each other, allowing detectors to determine their point of origin accurately (as shown in [Figure 22.5]). It requires detectors on opposite sides to simultaneously (i.e., at the same time) detect photons of 0.511 MeV energy and utilizes computer imaging techniques similar to those in SPECT and CT scans. PET is used extensively for diagnosing brain disorders. It can note decreased metabolism in certain regions that accompany Alzheimer’s disease. PET can also locate regions in the brain that become active when a person carries out specific activities, such as speaking, closing his or her eyes, and so on."],"figures":[{"sourceId":"fs-id1167063798676","filename":"CNX_HSPhysics_22_05_Radiopharm.jpg","relativePath":"media/CNX_HSPhysics_22_05_Radiopharm.jpg","alt":"The figure shows brain image of a patient with Alzheimer’s disease."},{"sourceId":"fs-id1167067087863","filename":"CNX_HSPhysics_22_05_Anger.jpg","relativePath":"media/CNX_HSPhysics_22_05_Anger.jpg","alt":"The figure shows the working of an Anger camera (or gamma camera) with the input rays on the left, camera in the centre and output on the right (which is used for image construction)."},{"sourceId":"fs-id1167063520605","filename":"CNX_HSPhysics_22_05_SPECT.jpg","relativePath":"media/CNX_HSPhysics_22_05_SPECT.jpg","alt":"A photo showing the equipment for Single-photon-emission computer tomography (SPECT)."},{"sourceId":"fs-id1167067036068","filename":"CNX_HSPhysics_22_05_PET.jpg","relativePath":"media/CNX_HSPhysics_22_05_PET.jpg","alt":"The figure shows the equipment for Positron emission tomography (PET)."}],"tables":[]},{"uid":"hsphys.ch22.sec05.sub02","title":"Ionizing Radiation on the Body","summaryVi":null,"paragraphs":["We hear many seemingly contradictory things about the biological effects of ionizing radiation . It can cause cancer, burns, and hair loss, and yet it is used to treat and even cure cancer. How do we understand such effects? Once again, there is an underlying simplicity in nature, even in complicated biological organisms. All the effects of ionizing radiation on biological tissue can be understood by knowing that ionizing radiation affects molecules within cells, particularly DNA molecules. Let us take a brief look at molecules within cells and how cells operate. Cells have long, double-helical DNA molecules containing chemical patterns called genetic codes that govern the function and processes undertaken by the cells. Damage to DNA consists of breaks in chemical bonds or other changes in the structural features of the DNA chain, leading to changes in the genetic code. In human cells, we can have as many as a million individual instances of damage to DNA per cell per day. The repair ability of DNA is vital for maintaining the integrity of the genetic code and for the normal functioning of the entire organism. A cell with a damaged ability to repair DNA, which could have been induced by ionizing radiation, can do one of the following:","Since ionizing radiation damages the DNA, ionizing radiation has its greatest effect on cells that rapidly reproduce, including most types of cancer. Thus, cancer cells are more sensitive to radiation than normal cells and can be killed by it easily. Cancer is characterized by a malfunction of cell reproduction, and can also be caused by ionizing radiation. There is no contradiction to say that ionizing radiation can be both a cure and a cause.","Radiotherapy is effective against cancer because cancer cells reproduce rapidly and, consequently, are more sensitive to radiation. The central problem in radiotherapy is to make the dose for cancer cells as high as possible while limiting the dose for normal cells. The ratio of abnormal cells killed to normal cells killed is called the therapeutic ratio , and all radiotherapy techniques are designed to enhance that ratio. Radiation can be concentrated in cancerous tissue by a number of techniques. One of the most prevalent techniques for well-defined tumors is a geometric technique shown in [Figure 22.5]. A narrow beam of radiation is passed through the patient from a variety of directions with a common crossing point in the tumor. The technique concentrates the dose in the tumor while spreading it out over a large volume of normal tissue.","Another use of radiation therapy is through radiopharmaceuticals. Cleverly, radiopharmaceuticals are used in cancer therapy by tagging antibodies with radioisotopes. Those antibodies are extracted from the patient, cultured, loaded with a radioisotope, and then returned to the patient. The antibodies are then concentrated almost entirely in the tissue they developed to fight, thus localizing the radiation in abnormal tissue. This method is used with radioactive iodine to fight thyroid cancer. While the therapeutic ratio can be quite high for such short-range radiation, there can be a significant dose for organs that eliminate radiopharmaceuticals from the body, such as the liver, kidneys, and bladder. As with most radiotherapy, the technique is limited by the tolerable amount of damage to the normal tissue."],"figures":[{"sourceId":"fs-id1167067184600","filename":"CNX_HSPhysics_22_05_Radio.jpg","relativePath":"media/CNX_HSPhysics_22_05_Radio.jpg","alt":"The figure shows the use of radiotherapy for treating tumors. A patient is lying and gamma rays are passed through him from several directions and concentrated on the tumor point."}],"tables":[]},{"uid":"hsphys.ch22.sec05.sub03","title":"Radiation Dosage","summaryVi":null,"paragraphs":["To quantitatively discuss the biological effects of ionizing radiation, we need a radiation dose unit that is directly related to those effects. To do define such a unit, it is important to consider both the biological organism and the radiation itself. Knowing that the amount of ionization is proportional to the amount of deposited energy, we define a radiation dose unit called the rad . It 1/100 of a joule of ionizing energy deposited per kilogram of tissue, which is","For example, if a 50.0-kg person is exposed to ionizing radiation over her entire body and she absorbs 1.00 J, then her whole-body radiation dose is","If the same 1.00 J of ionizing energy were absorbed in her 2.00-kg forearm alone, then the dose to the forearm would be","and the unaffected tissue would have a zero rad dose. When calculating radiation doses, you divide the energy absorbed by the mass of affected tissue. You must specify the affected region, such as the whole body or forearm in addition to giving the numerical dose in rads. Although the energy per kilogram in 1 rad is small, it can still have significant effects. Since only a few eV cause ionization, just 0.01 J of ionizing energy can create a huge number of ion pairs and have an effect at the cellular level.","The effects of ionizing radiation may be directly proportional to the dose in rads, but they also depend on the type of radiation and the type of tissue. That is, for a given dose in rads, the effects depend on whether the radiation is \\(\\alpha\\), \\(\\beta\\), \\(\\gamma\\), X-ray, or some other type of ionizing radiation. The relative biological effectiveness (RBE) relates to the amount of biological damage that can occur from a given type of radiation and is given in [Table_22_04] for several types of ionizing radiation.","A final dose unit more closely related to the effect of radiation on biological tissue is called the roentgen equivalent man , or rem. A combination of all factors mentioned previously, the roentgen equivalent man is defined to be the dose in rads multiplied by the relative biological effectiveness.","The large-scale effects of radiation on humans can be divided into two categories: immediate effects and long-term effects. [Table_22_05] gives the immediate effects of whole-body exposures received in less than one day. If the radiation exposure is spread out over more time, greater doses are needed to cause the effects listed. Any dose less than 10 rem is called a low dose, a dose 10 to 100 rem is called a moderate dose, and anything greater than 100 rem is called a high dose."],"figures":[],"tables":[{"sourceId":"Table_22_04","headers":["Type and energy of radiation","RBE"],"rows":[["X-rays","1"],["\\(\\gamma\\) rays","1"],["\\(\\beta\\) rays greater than 32 keV","1"],["\\(\\beta\\) rays less than 32 keV","1.7"],["Neutrons, thermal to slow (< 20 keV)","2–5"],["Neutrons, fast (1–10 MeV)","10 (body), 32 (eyes)"],["Protons (1–10 MeV)","10 (body), 32 (eyes)"],["\\(\\alpha\\) rays from radioactive decay","10–20"],["Heavy ions from accelerators","10–20"]]},{"sourceId":"Table_22_05","headers":["Dose (rem)","Effect"],"rows":[["0–10","No observable effect"],["10–100","Slight to moderate decrease in white blood cell counts"],["50","Temporary sterility"],["100–200","Significant reduction in blood cell counts, brief nausea, and vomiting; rarely fatal"],["200–500","Nausea, vomiting, hair loss, severe blood damage, hemorrhage, fatalities"],["450","LD50/32; lethal to 50% of the population within 32 days after exposure if untreated"],["500–2,000","Worst effects due to malfunction of small intestine and blood systems; limited survival"],["> 2,000","Fatal within hours due to collapse of central nervous system"]]}]},{"uid":"hsphys.ch22.sec05.sub04","title":"Performance Task","summaryVi":null,"paragraphs":["On the Environmental Protection Agency’s website, a helpful tool exists to allow you to determine your average annual radiation dose. Use the tool to determine whether the radiation level you have been exposed to is dangerous and to compare your radiation dosage to other radiative events.","Provide one question based upon the information gathered on the EPA website."],"figures":[],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch22.sec05.feat01","type":"tip","title":"Tips for Success","text":"The RBEs given in [Table_22_04] are approximate, but they yield certain valuable insights.\nThe eyes are more sensitive to radiation, because the cells of the lens do not repair themselves.\nThough both are neutral and have large ranges, neutrons cause more damage than \\(\\gamma\\) rays because neutrons often cause secondary radiation when they are captured.\nShort-range particles such as \\(\\alpha\\) rays have a severely damaging effect to internal anatomy, as their damage is concentrated and more difficult for the biological organism to repair. However, the skin can usually block alpha particles from entering the body.\nCan you think of any other insights from the table?","images":[]},{"uid":"hsphys.ch22.sec05.feat02","type":"physics-in-action","title":"Health Physicist","text":"Are you interested in learning more about radiation? Are you curious about studying radiation dosage levels and ensuring the safety of the environment and people that are most closely affected by it? If so, you may be interested in becoming a health physicist.\nThe field of health physics draws from a variety of science disciplines with the central aim of mitigating radiation concerns. Those that work as health physicists have a diverse array of potential jobs available to them, including those in research, industry, education, environmental protection, and governmental regulation. Furthermore, while the term health physicist may lead many to think of the medical field, there are plenty of applications within the military, industrial, and energy fields as well.\nAs a researcher, a health physicist can further environmental studies on the effects of radiation, design instruments for more accurate measurements, and assist in establishing valuable radiation standards. Within the energy field, a health physicsist often acts as a manager, closely tied to all operations at all levels, from procuring appropirate equipment to monitoring health data. Within industry, the health physicist acts as a consultant, assisting industry management in important decisions, designing facilities, and choosing appropriate detection tools. The health physicist possesses a unique knowledge base that allows him or her to operate in a wide variety of interesting disciplines!\nTo become a health physicist, it is necessary to have a background in the physical sciences. Understanding the fields of biology, physiology, biochemistry, and genetics are all important as well. The ability to analyze and solve new problems is critical, and a natural aptitude for science and mathematics will assist in the continued necessary training. There are two possible certifications for health physicists: from the American Board of Health Physicists (ABHP) and the National Registry of Radiation Protection Technologists (NRRPT).","images":[]}],"summaryPoints":["Medical imaging occurs when a radiopharmaceutical placed in the body provides information to an array of radiation detectors outside the body.","Devices utilizing medical imaging include the Anger camera, SPECT detector, and PET scan.","Ionizing radiation can both cure and cause cancer through the manipulation of DNA molecules.","Radiation dosage and its effect on the body can be measured using the quantities radiation dose unit (rad), relative biological effectiveness (RBE), and the roentgen equivalent man (rem)."],"glossary":[{"term":"anger camera","termVi":"Camera gamma (Máy chụp nhấp nháy Anger)","definition":"common medical imaging device that uses a scintillator connected to a series of photomultipliers","definitionVi":"Thiết bị y tế thu nhận tia gamma phát ra từ dược chất phóng xạ trong cơ thể để dựng ảnh cơ quan nội tạng.","memoryTipVi":"Đặt theo tên nhà phát minh Hal Anger."},{"term":"rad","termVi":"Rad (Đơn vị liều hấp thụ bức xạ)","definition":"amount of ionizing energy deposited per kilogram of tissue","definitionVi":"Đơn vị đo năng lượng bức xạ hấp thụ trên 1 kg mô (1 Gy = 100 rad).","memoryTipVi":"Radiation Absorbed Dose."},{"term":"radiopharmaceutical","termVi":"Dược chất phóng xạ","definition":"compound used for medical imaging","definitionVi":"Hợp chất gắn đồng vị phóng xạ đưa vào cơ thể để chẩn đoán hình ảnh (PET/SPECT) hoặc xạ trị ung thư.","memoryTipVi":"Thường chọn đồng vị có chu kỳ bán rã ngắn để an toàn."},{"term":"relative biological effectiveness (RBE)","termVi":"Hệ số hiệu quả sinh học tương đối (RBE)","definition":"number that expresses the relative amount of damage that a fixed amount of ionizing radiation of a given type can inflict on biological tissues","definitionVi":"Hệ số cho biết mức độ gây tổn thương mô sống của loại tia bức xạ (tia α có RBE cao gấp ~20 lần tia γ).","memoryTipVi":"Hạt nặng ion hóa mạnh → RBE cao."},{"term":"roentgen equivalent man (rem)","termVi":"Rem (Đơn vị liều tương đương sinh học)","definition":"dose unit more closely related to effects in biological tissue","definitionVi":"Liều bức xạ đã nhân hệ số sinh học: rem = rad × RBE (1 Sievert = 100 rem).","memoryTipVi":"Đánh giá mức độ nguy hiểm thực sự đối với cơ thể người."},{"term":"tagged","termVi":"Được đánh dấu phóng xạ","definition":"having a radioactive substance attached (to a chemical compound)","definitionVi":"Phân tử sinh học được gắn nguyên tử đồng vị phóng xạ để theo dõi đường đi trong cơ thể.","memoryTipVi":"Radioactive tracer."},{"term":"therapeutic ratio","termVi":"Tỉ số điều trị xạ trị","definition":"the ratio of abnormal cells killed to normal cells killed","definitionVi":"Tỉ lệ liều tiêu diệt tế bào ung thư so với liều gây hại cho mô lành xung quanh.","memoryTipVi":"Mục tiêu xạ trị là tối đa hóa tỉ số này."}],"assessments":[],"stats":{"learningObjectiveCount":2,"keyEquationCount":1,"subsectionCount":4,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":7,"assessmentCount":0}}],"summary":{"totalSections":6,"totalKeyEquations":6,"totalWorkedExamples":8,"totalSnapLabs":0,"totalGlossaryTerms":42,"totalAssessments":8,"referencedMediaCount":41},"qualityGate":{"passed":true,"checkedUids":48,"errors":[],"warnings":[]}};
